import React, { useState, useEffect } from 'react';
import { 
  DollarSign, 
  Car, 
  Package, 
  TrendingUp, 
  PlusCircle, 
  Sparkles,
  ChevronRight,
  FileText,
  Loader2,
  Calendar
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { ServiceOrder, Part, OSStatus, UserSession } from '../types';
import { GoogleGenAI } from "@google/genai";

const Dashboard: React.FC<{ session?: UserSession }> = ({ session }) => {
  const navigate = useNavigate();
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const [orders, setOrders] = useState<ServiceOrder[]>([]);
  const [parts, setParts] = useState<Part[]>([]);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  useEffect(() => {
    if (session) {
      const savedOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      const savedParts = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_parts`) || '[]');
      setOrders(savedOrders);
      setParts(savedParts);
      fetchAiInsights(savedOrders, savedParts);
    }
  }, [session]);

  const fetchAiInsights = async (currentOrders: ServiceOrder[], currentParts: Part[]) => {
    setIsAiLoading(true);
    try {
      const prompt = `Analise os dados desta oficina mecânica: ${currentOrders.length} ordens de serviço e ${currentParts.length} itens no estoque. Forneça um insight estratégico de 2 frases para o dono da oficina aumentar o lucro hoje.`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      setAiInsight(response.text || 'Otimize seu fluxo de caixa finalizando as OS pendentes.');
    } catch (err) {
      setAiInsight('Planejamento estratégico: Avalie o estoque de peças de giro rápido para não perder vendas hoje.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const dailyFinished = orders.filter(o => new Date(o.updatedAt).toDateString() === new Date().toDateString() && o.status === OSStatus.FINALIZADO);
  const dailyRevenue = dailyFinished.reduce((acc, curr) => acc + curr.totalValue, 0);
  const criticalStock = parts.filter(p => p.stock <= p.minStock).length;

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-20">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 italic uppercase tracking-tighter">Centro de <span className="text-[#E11D48]">Performance</span></h1>
          <p className="text-slate-500 font-bold text-[10px] uppercase tracking-[0.2em] flex items-center gap-2">
            <Calendar size={12} className="text-[#E11D48]" /> Dashboard Ativo • {session?.username}
          </p>
        </div>
        <button 
          onClick={() => navigate('/orders/new')} 
          className="bg-[#E11D48] text-white px-8 py-4 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center gap-3 shadow-lg shadow-red-100 hover:scale-105 transition-all"
        >
          <PlusCircle size={18} /> Nova Ordem de Serviço
        </button>
      </div>

      {/* IA INSIGHT - NOVO ESTILO LIGHT */}
      <div className="bg-white border border-red-100 p-8 rounded-[2.5rem] shadow-sm relative overflow-hidden group">
        <div className="absolute top-0 right-0 p-8 text-red-50 opacity-50 group-hover:scale-110 transition-transform"><Sparkles size={80}/></div>
        <div className="flex items-center gap-3 mb-4">
          <div className="p-2 bg-red-50 text-[#E11D48] rounded-xl"><Sparkles size={18}/></div>
          <h3 className="text-[10px] font-black text-[#E11D48] uppercase tracking-[0.3em] italic">Kaenpro Smart Insight</h3>
        </div>
        {isAiLoading ? (
          <div className="flex items-center gap-4 text-slate-400 italic"><Loader2 className="animate-spin" size={18}/> <span className="text-sm font-medium">IA analisando métricas de hoje...</span></div>
        ) : (
          <p className="text-xl font-black text-slate-800 italic leading-tight max-w-2xl">{aiInsight}</p>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <div className="bg-white border border-slate-200 p-8 rounded-[2.5rem] shadow-sm group hover:border-[#E11D48]/30 transition-all">
          <p className="text-slate-400 text-[9px] font-black uppercase mb-1 tracking-widest">Faturamento Hoje</p>
          <div className="flex items-center justify-between">
            <p className="text-3xl font-black text-slate-900 italic">R$ {dailyRevenue.toLocaleString('pt-BR')}</p>
            <TrendingUp size={24} className="text-emerald-500" />
          </div>
          <div className="mt-4 h-1 bg-slate-100 rounded-full overflow-hidden"><div className="h-full bg-emerald-500 w-[70%]"></div></div>
        </div>

        <div className="bg-white border border-slate-200 p-8 rounded-[2.5rem] shadow-sm">
          <p className="text-slate-400 text-[9px] font-black uppercase mb-1 tracking-widest">Veículos Entregues</p>
          <p className="text-3xl font-black text-slate-900 italic">{dailyFinished.length}</p>
        </div>

        <div className="bg-white border border-slate-200 p-8 rounded-[2.5rem] shadow-sm">
          <p className="text-slate-400 text-[9px] font-black uppercase mb-1 tracking-widest">Pátio em Execução</p>
          <p className="text-3xl font-black text-slate-900 italic">{orders.filter(o => o.status === OSStatus.EM_ANDAMENTO).length}</p>
        </div>

        <div className="bg-white border border-slate-200 p-8 rounded-[2.5rem] shadow-sm">
          <p className="text-slate-400 text-[9px] font-black uppercase mb-1 tracking-widest">Estoque em Alerta</p>
          <p className={`text-3xl font-black italic ${criticalStock > 0 ? 'text-red-500' : 'text-slate-900'}`}>{criticalStock}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white border border-slate-200 p-8 rounded-[3rem] shadow-sm">
          <div className="flex justify-between items-center mb-8">
            <h3 className="font-black text-[10px] text-slate-400 flex items-center gap-2 uppercase tracking-widest italic"><FileText size={14} className="text-[#E11D48]"/> Últimos Serviços</h3>
            <button onClick={() => navigate('/orders')} className="text-[9px] font-black uppercase text-slate-400 hover:text-slate-900 transition-all">Ver Histórico</button>
          </div>
          <div className="space-y-3">
            {dailyFinished.slice(-4).map((o, i) => (
              <div key={i} className="flex items-center justify-between p-5 bg-slate-50/50 border border-slate-100 rounded-3xl hover:bg-slate-50 transition-colors">
                <div>
                  <p className="text-xs font-black text-slate-900 uppercase italic">{o.clientName}</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase">{o.vehiclePlate} • {o.vehicleModel}</p>
                </div>
                <p className="text-sm font-black text-slate-900">R$ {o.totalValue.toLocaleString()}</p>
              </div>
            ))}
          </div>
        </div>

        <div className="bg-white border border-slate-200 p-8 rounded-[3rem] shadow-sm">
           <h3 className="font-black text-[10px] text-slate-400 flex items-center gap-2 uppercase tracking-widest italic mb-8"><Package size={14} className="text-amber-500"/> Alertas de Reposição</h3>
           <div className="space-y-3">
            {parts.filter(p => p.stock <= p.minStock).slice(0, 4).map((p, i) => (
              <div key={i} className="flex items-center justify-between p-5 bg-orange-50/30 border border-orange-100 rounded-3xl">
                <div>
                  <p className="text-xs font-black text-slate-900 uppercase italic">{p.name}</p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase">SKU: {p.sku}</p>
                </div>
                <div className="text-right">
                  <span className="bg-white px-3 py-1 rounded-lg border border-orange-200 text-orange-600 font-black text-[10px]">{p.stock} UN</span>
                </div>
              </div>
            ))}
            {parts.filter(p => p.stock <= p.minStock).length === 0 && (
              <div className="py-10 text-center">
                <p className="text-xs font-bold text-slate-400 italic">Estoque saudável. Nenhuma peça em alerta.</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

