import { NavLink } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Users, 
  Car, 
  PlusSquare, 
  FileText, 
  Package, 
  UserCheck,
  Settings,
  Wrench,
  ChevronRight,
  DollarSign,
  Smartphone,
  X,
  PieChart,
  CalendarDays
} from 'lucide-react';

