            <div 
              ref={invoiceRef} 
              className="w-full max-w-[360px] aspect-[9/16] bg-white text-zinc-900 rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col p-10 border-[12px] border-zinc-100"
