import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Trash2, Wrench, Package, ChevronLeft, X, Smartphone,
  User, Car, Search, Loader2, Download, DollarSign, Sparkles,
  CreditCard, Wallet, Share2, Printer, CheckCircle2, FileText,
  MessageCircle, Edit3, Save, ArrowRight
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Client, Vehicle, OSItem, OSStatus, ServiceOrder, PaymentStatus, UserSession, PaymentMethod, TransactionType, FinancialTransaction } from '../types';
import html2canvas from 'html2canvas';

const NewServiceOrder: React.FC<{ session?: UserSession; syncData?: (key: string, data: any) => Promise<void> }> = ({ session, syncData }) => {
  const navigate = useNavigate();
  const invoiceRef = useRef<HTMLDivElement>(null);

  // Fluxo de Etapas
  const [step, setStep] = useState<'CLIENT' | 'ITEMS' | 'REVIEW' | 'FINAL'>('CLIENT');

  // Estados de Dados
  const [clients, setClients] = useState<Client[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);

  // Itens da Nota
  const [items, setItems] = useState<OSItem[]>([]);
  const [labor, setLabor] = useState<string>('0');
  const [discount, setDiscount] = useState<string>('0');
  const [km, setKm] = useState('');
  const [obs, setObs] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.PIX);

  const [finalOs, setFinalOs] = useState<ServiceOrder | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (session) {
      const savedClients = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_clients`) || '[]');
      const savedVehicles = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_vehicles`) || '[]');
      setClients(savedClients);
      setVehicles(savedVehicles);
    }
  }, [session]);

  const filteredClients = useMemo(() => {
    if (!clientSearch.trim()) return [];
    return clients.filter(c => 
      c.name.toLowerCase().includes(clientSearch.toLowerCase()) || 
      c.phone.includes(clientSearch)
    );
  }, [clientSearch, clients]);

  const clientVehicles = useMemo(() => {
    return selectedClient ? vehicles.filter(v => v.clientId === selectedClient.id) : [];
  }, [selectedClient, vehicles]);

  const subtotal = useMemo(() => {
    const itemsTotal = items.reduce((acc, curr) => acc + (curr.quantity * curr.unitPrice), 0);
    return itemsTotal + (parseFloat(labor) || 0);
  }, [items, labor]);

  const totalValue = useMemo(() => {
    return Math.max(0, subtotal - (parseFloat(discount) || 0));
  }, [subtotal, discount]);

  const addItem = () => {
    setItems([...items, { id: Math.random().toString(36).substr(2, 9), description: '', quantity: 1, unitPrice: 0, type: 'PART' }]);
  };

  const updateItem = (id: string, field: keyof OSItem, value: any) => {
    setItems(items.map(i => i.id === id ? { ...i, [field]: value } : i));
  };

  const removeItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const handleFinalize = async () => {
    if (!selectedClient || !selectedVehicle || !session || !syncData) return;
    setIsSaving(true);

    try {
      const osNumber = `N-${Date.now().toString().slice(-6)}`;
      const osId = Math.random().toString(36).substr(2, 9);

      const os: ServiceOrder = {
        id: osId,
        osNumber,
        clientId: selectedClient.id,
        clientName: selectedClient.name,
        vehicleId: selectedVehicle.id,
        vehiclePlate: selectedVehicle.plate,
        vehicleModel: selectedVehicle.model,
        vehicleKm: km,
        problem: obs || 'Serviço Geral',
        items,
        laborValue: parseFloat(labor) || 0,
        discount: parseFloat(discount) || 0,
        totalValue,
        status: OSStatus.FINALIZADO,
        paymentStatus: PaymentStatus.PAGO,
        paymentMethod,
        observations: obs,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      // Criação automática da transação financeira
      const transaction: FinancialTransaction = {
        id: Math.random().toString(36).substr(2, 9),
        type: TransactionType.INCOME,
        category: 'Serviço/Venda',
        amount: totalValue,
        method: paymentMethod,
        description: `Nota #${osNumber} - ${selectedVehicle.plate}`,
        relatedId: osId,
        date: new Date().toISOString()
      };

      // Busca dados atuais para não sobrescrever
      const currentOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      const currentTransactions = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_transactions`) || '[]');

      // Sincroniza ambos os módulos
      await syncData('orders', [...currentOrders, os]);
      await syncData('transactions', [...currentTransactions, transaction]);

      setFinalOs(os);
      setStep('FINAL');
    } catch (error) {
      alert("Erro ao salvar nota. Tente novamente.");
    } finally {
      setIsSaving(false);
    }
  };

  const downloadInvoice = async () => {
    if (!invoiceRef.current) return;
    const canvas = await html2canvas(invoiceRef.current, { scale: 2, backgroundColor: '#ffffff' });
    const link = document.createElement('a');
    link.download = `Nota_${finalOs?.osNumber}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const shareWhatsApp = () => {
    if (!finalOs) return;
    const text = `*COMPROVANTE KAENPRO*\n\nNota: #${finalOs.osNumber}\nCliente: ${finalOs.clientName}\nVeículo: ${finalOs.vehiclePlate}\nValor: R$ ${finalOs.totalValue.toLocaleString('pt-BR')}\n\nObrigado pela preferência!`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  return (
    <div className="flex flex-col h-full bg-[#0B0B0B] text-white overflow-hidden">
      {/* Header Fixo */}
      <div className="p-4 border-b border-zinc-800 flex items-center justify-between sticky top-0 bg-[#0B0B0B] z-20">
        <button onClick={() => navigate(-1)} className="p-2 text-zinc-500 hover:text-white transition-colors">
          <ChevronLeft size={24} />
        </button>
        <h2 className="text-sm font-black uppercase tracking-widest italic">Nova <span className="text-[#E11D48]">Nota Pro</span></h2>
        <div className="w-10"></div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 no-scrollbar pb-32">
        {step === 'CLIENT' && (
          <div className="space-y-6 animate-in slide-in-from-bottom duration-300">
            <div className="bg-zinc-900/50 p-6 rounded-3xl border border-zinc-800">
              <h3 className="text-[10px] font-black uppercase text-zinc-500 mb-4 tracking-widest">1. Selecionar Cliente</h3>
              {!selectedClient ? (
                <div className="space-y-4">
                  <div className="relative">
                    <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-zinc-600" size={18} />
                    <input 
                      type="text" value={clientSearch} onChange={(e) => setClientSearch(e.target.value)}
                      placeholder="Nome ou Telefone..."
                      className="w-full bg-zinc-950 border border-zinc-800 rounded-2xl py-4 pl-12 pr-4 text-sm font-bold outline-none focus:border-[#E11D48]"
                    />
                  </div>
                  <div className="max-h-40 overflow-y-auto space-y-2 no-scrollbar">
                    {filteredClients.map(c => (
                      <button key={c.id} onClick={() => setSelectedClient(c)} className="w-full p-4 bg-zinc-950 rounded-xl flex items-center justify-between border border-transparent hover:border-[#E11D48]">
                        <span className="font-bold text-xs uppercase">{c.name}</span>
                        <Plus size={14} className="text-[#E11D48]" />
                      </button>
                    ))}
                    {clientSearch && filteredClients.length === 0 && <p className="text-center text-[10px] text-zinc-600 uppercase font-black py-4">Nenhum cliente encontrado</p>}
                  </div>
                </div>
              ) : (
                <div className="flex items-center justify-between bg-zinc-950 p-4 rounded-xl border border-emerald-500/20">
                  <div className="flex items-center gap-3">
                    <User className="text-emerald-500" size={18} />
                    <span className="font-black text-xs uppercase">{selectedClient.name}</span>
                  </div>
                  <button onClick={() => { setSelectedClient(null); setSelectedVehicle(null); }} className="text-zinc-600 hover:text-white"><X size={18}/></button>
                </div>
              )}
            </div>

            {selectedClient && (
              <div className="bg-zinc-900/50 p-6 rounded-3xl border border-zinc-800 animate-in fade-in">
                <h3 className="text-[10px] font-black uppercase text-zinc-500 mb-4 tracking-widest">2. Selecionar Veículo</h3>
                <div className="grid grid-cols-2 gap-2">
                  {clientVehicles.map(v => (
                    <button 
                      key={v.id} onClick={() => setSelectedVehicle(v)}
                      className={`p-4 rounded-xl border-2 transition-all flex flex-col items-center gap-2 ${selectedVehicle?.id === v.id ? 'border-[#E11D48] bg-[#E11D48]/10 text-white shadow-[0_0_15px_rgba(225,29,72,0.1)]' : 'border-zinc-800 bg-zinc-950 text-zinc-600'}`}
                    >
                      <Car size={18} />
                      <span className="font-black text-[10px] tracking-widest">{v.plate}</span>
                    </button>
                  ))}
                </div>
                {selectedVehicle && (
                  <button onClick={() => setStep('ITEMS')} className="w-full mt-6 bg-[#E11D48] py-4 rounded-xl font-black uppercase text-[10px] tracking-widest shadow-lg">
                    Próximo: Itens da Nota
                  </button>
                )}
              </div>
            )}
          </div>
        )}

        {step === 'ITEMS' && (
          <div className="space-y-6 animate-in slide-in-from-right duration-300">
            <div className="bg-zinc-900/50 p-6 rounded-3xl border border-zinc-800 space-y-4">
              <div className="flex items-center justify-between">
                <h3 className="text-[10px] font-black uppercase text-zinc-500 tracking-widest">3. Serviços e Peças</h3>
