                <div>
                  <label className="text-[8px] font-black text-zinc-600 uppercase mb-1 block">Desconto (R$)</label>
                  <input type="number" value={discount} onChange={(e) => setDiscount(e.target.value)} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-sm font-black text-[#E11D48]" />
                </div>
              </div>

              <div>
                <label className="text-[8px] font-black text-zinc-600 uppercase mb-1 block">Forma de Pagamento</label>
                <select 
                  value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value as PaymentMethod)}
