        )}

        {step === 'FINAL' && finalOs && (
          <div className="space-y-6 animate-in zoom-in duration-300 flex flex-col items-center">
            {/* NOTA 9:16 PARA COMPARTILHAMENTO */}
            <div 
              ref={invoiceRef}
              className="w-full max-w-[320px] aspect-[9/16] bg-white text-zinc-900 rounded-[2rem] overflow-hidden shadow-2xl flex flex-col p-6 border-8 border-zinc-100"
            >
              <div className="flex justify-between items-start mb-6 border-b border-zinc-100 pb-4">
                <div className="flex items-center gap-2">
                  <div className="w-8 h-8 bg-zinc-900 rounded-lg flex items-center justify-center text-white"><Wrench size={16}/></div>
                  <h1 className="text-sm font-black tracking-tighter uppercase leading-none">KAEN<span className="text-[#E11D48]">PRO</span></h1>
                </div>
                <div className="text-right">
                  <p className="text-[7px] font-black text-zinc-400 uppercase tracking-widest">NOTA #{finalOs.osNumber}</p>
                  <p className="text-[8px] font-black text-zinc-900">{new Date(finalOs.createdAt).toLocaleDateString('pt-BR')}</p>
                </div>
              </div>

              <div className="space-y-3 mb-6">
                <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                  <p className="text-[6px] font-black text-zinc-400 uppercase tracking-widest mb-1">Cliente</p>
                  <p className="text-[10px] font-black uppercase italic">{finalOs.clientName}</p>
                </div>
                <div className="grid grid-cols-2 gap-2">
                   <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                    <p className="text-[6px] font-black text-zinc-400 uppercase tracking-widest mb-1">Veículo</p>
                    <p className="text-[9px] font-black uppercase italic truncate">{finalOs.vehicleModel}</p>
                  </div>
                  <div className="bg-zinc-50 p-3 rounded-xl border border-zinc-100">
                    <p className="text-[6px] font-black text-zinc-400 uppercase tracking-widest mb-1">Placa</p>
                    <p className="text-[9px] font-black uppercase italic text-[#E11D48]">{finalOs.vehiclePlate}</p>
                  </div>
                </div>
              </div>

              <div className="flex-1 overflow-hidden">
                <table className="w-full text-left text-[8px]">
                  <thead className="border-b border-zinc-100">
                    <tr className="font-black text-zinc-400 uppercase"><th className="pb-1">Item</th><th className="pb-1 text-right">Valor</th></tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-50 font-medium">
                    {finalOs.items.map((i,idx)=>(
                      <tr key={idx}><td className="py-2 uppercase">{i.description}</td><td className="py-2 text-right font-black">R$ {(i.quantity*i.unitPrice).toLocaleString()}</td></tr>
                    ))}
                    {finalOs.laborValue > 0 && (
                      <tr><td className="py-2 font-black uppercase">Mão de Obra</td><td className="py-2 text-right font-black">R$ {finalOs.laborValue.toLocaleString()}</td></tr>
                    )}
                  </tbody>
                </table>
              </div>

              <div className="mt-4 pt-4 border-t-2 border-zinc-100">
                <div className="flex justify-between items-center mb-1 text-[7px] opacity-40 uppercase font-black">
                  <span>Subtotal</span>
                  <span>R$ {subtotal.toLocaleString()}</span>
                </div>
                {finalOs.discount > 0 && (
                  <div className="flex justify-between items-center mb-2 text-[7px] text-[#E11D48] font-black uppercase">
                    <span>Desconto</span>
                    <span>- R$ {finalOs.discount.toLocaleString()}</span>
                  </div>
                )}
                <div className="flex justify-between items-center">
                   <div className="text-left">
                     <p className="text-[6px] font-black text-zinc-400 uppercase italic">Pago via</p>
                     <p className="text-[8px] font-black uppercase bg-zinc-900 text-white px-1.5 py-0.5 rounded leading-none">{finalOs.paymentMethod}</p>
                   </div>
                   <p className="text-2xl font-black italic text-zinc-900 leading-none">R$ {finalOs.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
              </div>

              <div className="mt-6 text-center">
                 <p className="text-[6px] font-black text-zinc-300 uppercase tracking-[0.3em]">Obrigado pela preferência!</p>
              </div>
            </div>

            <div className="w-full space-y-3">
              <button onClick={shareWhatsApp} className="w-full bg-[#25D366] py-4 rounded-xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2 shadow-lg">
                <MessageCircle size={18} /> Compartilhar WhatsApp
              </button>
              <div className="grid grid-cols-2 gap-2">
                <button onClick={downloadInvoice} className="bg-zinc-800 py-4 rounded-xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2">
                  <Download size={16} /> Salvar PNG
                </button>
                <button onClick={() => window.print()} className="bg-zinc-800 py-4 rounded-xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2">
                  <Printer size={16} /> Imprimir
                </button>
              </div>
              <button onClick={() => navigate('/orders')} className="w-full bg-zinc-900 border border-zinc-800 py-4 rounded-xl font-black uppercase text-[10px] tracking-widest text-zinc-500">
                Ir para Histórico
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

