import React, { useState, useEffect, useMemo } from 'react';
import { 
  DollarSign, ArrowUpCircle, ArrowDownCircle, TrendingUp, PieChart as PieChartIcon, 
  Plus, Calendar, Search, X, Trash2, Edit3, Loader2, Save
} from 'lucide-react';
import { FinancialTransaction, TransactionType, PaymentMethod, UserSession } from '../types';

const Financial: React.FC<{ session?: UserSession; syncData?: (key: string, data: any) => Promise<void> }> = ({ session, syncData }) => {
  const [transactions, setTransactions] = useState<FinancialTransaction[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [form, setForm] = useState({
    description: '',
    category: 'Diversos',
    amount: '',
    method: PaymentMethod.PIX,
    type: TransactionType.EXPENSE,
    date: new Date().toISOString().split('T')[0]
  });

  useEffect(() => {
    if (session) {
      const saved = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_transactions`) || '[]');
      setTransactions(saved);
    }
  }, [session]);

  const handleSave = async () => {
    if (!form.description || !form.amount || !session || !syncData) return;

    let updated: FinancialTransaction[];
    if (editingId) {
      updated = transactions.map(t => t.id === editingId ? {
        ...t,
        description: form.description,
        category: form.category,
        amount: parseFloat(form.amount),
        method: form.method,
        type: form.type,
        date: new Date(form.date).toISOString()
      } : t);
    } else {
      const newTransaction: FinancialTransaction = {
        id: Math.random().toString(36).substr(2, 9),
        type: form.type,
        category: form.category,
        amount: parseFloat(form.amount),
        method: form.method,
        description: form.description,
        date: new Date(form.date).toISOString()
      };
      updated = [...transactions, newTransaction];
    }

    setTransactions(updated);
    await syncData('transactions', updated);
    setShowModal(false);
    setEditingId(null);
    setForm({ description: '', category: 'Diversos', amount: '', method: PaymentMethod.PIX, type: TransactionType.EXPENSE, date: new Date().toISOString().split('T')[0] });
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Confirmar exclusão desta transação?")) return;
    const updated = transactions.filter(t => t.id !== id);
    setTransactions(updated);
    await syncData('transactions', updated);
  };

  const handleEdit = (t: FinancialTransaction) => {
    setEditingId(t.id);
    setForm({
      description: t.description,
      category: t.category,
      amount: t.amount.toString(),
      method: t.method,
      type: t.type,
      date: new Date(t.date).toISOString().split('T')[0]
    });
    setShowModal(true);
  };

  const totals = useMemo(() => {
    const income = transactions.filter(t => t.type === TransactionType.INCOME).reduce((a, b) => a + b.amount, 0);
    const expense = transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((a, b) => a + b.amount, 0);
    return { income, expense, balance: income - expense };
  }, [transactions]);

  const filtered = transactions.filter(t => 
    t.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    t.category.toLowerCase().includes(searchTerm.toLowerCase())
  ).reverse();

  return (
    <div className="space-y-6 animate-in fade-in duration-500 pb-24 h-full overflow-y-auto no-scrollbar scroll-smooth px-4">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mt-4">
        <div>
          <h1 className="text-3xl font-black text-white italic uppercase tracking-tighter">Fluxo de <span className="text-[#E11D48]">Caixa</span></h1>
          <p className="text-zinc-500 font-bold uppercase text-[10px] tracking-widest italic">Controle Cloud Integrado</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-zinc-800 text-white px-6 py-3 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2 shadow-lg active:scale-95 transition-all"
        >
          <Plus size={18} className="text-[#E11D48]" /> Novo Lançamento
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
        <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-3xl border-l-4 border-l-emerald-500">
           <p className="text-zinc-600 text-[9px] font-black uppercase tracking-widest mb-1">Entradas</p>
           <p className="text-2xl font-black text-emerald-500 italic">R$ {totals.income.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-3xl border-l-4 border-l-[#E11D48]">
           <p className="text-zinc-600 text-[9px] font-black uppercase tracking-widest mb-1">Saídas</p>
           <p className="text-2xl font-black text-[#E11D48] italic">R$ {totals.expense.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-zinc-900 border border-zinc-800 p-6 rounded-3xl border-l-4 border-l-blue-500">
           <p className="text-zinc-600 text-[9px] font-black uppercase tracking-widest mb-1">Saldo</p>
           <p className="text-2xl font-black text-white italic">R$ {totals.balance.toLocaleString('pt-BR')}</p>
        </div>
      </div>

      <div className="bg-zinc-900 border border-zinc-800 rounded-3xl shadow-xl overflow-hidden">
        <div className="p-4 border-b border-zinc-800 bg-zinc-950/20 flex items-center gap-3">
           <Search size={18} className="text-zinc-600" />
           <input type="text" value={searchTerm} onChange={(e)=>setSearchTerm(e.target.value)} placeholder="Pesquisar histórico..." className="bg-transparent border-none text-xs font-black uppercase w-full outline-none focus:ring-0 text-white"/>
        </div>

        <div className="divide-y divide-zinc-800/50">
           {filtered.map(t => (
             <div key={t.id} className="p-4 flex items-center justify-between gap-4 hover:bg-zinc-800/20 transition-all group">
                <div className="flex items-center gap-3">
                   <div className={`w-10 h-10 rounded-xl flex items-center justify-center border ${t.type === TransactionType.INCOME ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-[#E11D48]/10 border-[#E11D48]/20 text-[#E11D48]'}`}>
                      {t.type === TransactionType.INCOME ? <ArrowUpCircle size={18}/> : <ArrowDownCircle size={18}/>}
                   </div>
                   <div>
                      <p className="text-[11px] font-black text-white uppercase italic truncate max-w-[150px]">{t.description}</p>
                      <p className="text-[8px] font-bold text-zinc-600 uppercase tracking-widest">{new Date(t.date).toLocaleDateString('pt-BR')} • {t.category}</p>
                   </div>
                </div>

                <div className="flex items-center gap-6">
                   <div className="text-right">
                      <p className={`text-sm font-black italic ${t.type === TransactionType.INCOME ? 'text-emerald-500' : 'text-[#E11D48]'}`}>
                        R$ {t.amount.toLocaleString('pt-BR')}
                      </p>
                      <p className="text-[7px] font-bold text-zinc-700 uppercase tracking-widest">{t.method}</p>
                   </div>
                   <div className="flex gap-1">
                      <button onClick={()=>handleEdit(t)} className="p-2 bg-zinc-800 text-zinc-600 hover:text-white rounded-lg border border-zinc-800"><Edit3 size={14}/></button>
                      <button onClick={()=>handleDelete(t.id)} className="p-2 bg-zinc-800 text-zinc-600 hover:text-red-500 rounded-lg border border-zinc-800"><Trash2 size={14}/></button>
                   </div>
                </div>
             </div>
           ))}
           {filtered.length === 0 && <p className="text-center py-10 text-[9px] font-black text-zinc-700 uppercase italic">Nenhuma transação encontrada</p>}
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-md">
           <div className="bg-[#0c0c0e] border border-zinc-800 w-full max-w-lg p-8 rounded-[2rem] shadow-2xl relative animate-in zoom-in">
              <button onClick={() => { setShowModal(false); setEditingId(null); }} className="absolute top-6 right-6 text-zinc-500 hover:text-white"><X size={24} /></button>
              <h2 className="text-xl font-black text-white italic uppercase tracking-tighter mb-8">{editingId ? 'Editar Lançamento' : 'Novo Lançamento'}</h2>
              <div className="space-y-4">
                <div className="flex gap-2 p-1 bg-zinc-950 rounded-xl border border-zinc-800">
                  <button onClick={()=>setForm({...form, type: TransactionType.INCOME})} className={`flex-1 py-3 rounded-lg font-black text-[10px] uppercase transition-all ${form.type === TransactionType.INCOME ? 'bg-emerald-500 text-white shadow-lg shadow-emerald-900/20' : 'text-zinc-600'}`}>Entrada</button>
                  <button onClick={()=>setForm({...form, type: TransactionType.EXPENSE})} className={`flex-1 py-3 rounded-lg font-black text-[10px] uppercase transition-all ${form.type === TransactionType.EXPENSE ? 'bg-[#E11D48] text-white shadow-lg shadow-red-900/20' : 'text-zinc-600'}`}>Saída</button>
                </div>
                <div>
                  <label className="text-[9px] font-black text-zinc-600 uppercase mb-1 block">Descrição</label>
                  <input type="text" value={form.description} onChange={(e)=>setForm({...form, description: e.target.value.toUpperCase()})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-white font-bold text-xs"/>
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div>
                    <label className="text-[9px] font-black text-zinc-600 uppercase mb-1 block">Valor (R$)</label>
                    <input type="number" value={form.amount} onChange={(e)=>setForm({...form, amount: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-white font-black text-xs"/>
                  </div>
                  <div>
                    <label className="text-[9px] font-black text-zinc-600 uppercase mb-1 block">Data</label>
                    <input type="date" value={form.date} onChange={(e)=>setForm({...form, date: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-white font-black text-[10px]"/>
                  </div>
                </div>
                <div>
                  <label className="text-[9px] font-black text-zinc-600 uppercase mb-1 block">Método</label>
                  <select value={form.method} onChange={(e)=>setForm({...form, method: e.target.value as PaymentMethod})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-3 text-white font-bold text-xs">
                     {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                  </select>
                </div>
                <button onClick={handleSave} className="w-full bg-[#E11D48] py-4 rounded-xl font-black uppercase text-xs tracking-widest shadow-xl mt-4 active:scale-95 transition-all">
                  Confirmar Registro
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default Financial;

export enum OSStatus {
  ORCAMENTO = 'Orçamento',
  EM_ANDAMENTO = 'Em Execução',
  FINALIZADO = 'Finalizado',
  CANCELADO = 'Cancelado'
}

export enum PaymentStatus {
  PAGO = 'Pago',
  PENDENTE = 'Pendente',
  ATRASADO = 'Atrasado'
}

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE'
}

export enum PaymentMethod {
  PIX = 'PIX',
  DINHEIRO = 'Dinheiro',
  CARTAO_CREDITO = 'Cartão de Crédito',
  CARTAO_DEBITO = 'Cartão de Débito',
  OUTRO = 'Outro'
}

export interface FinancialTransaction {
  id: string;
  type: TransactionType;
  category: string;
  amount: number;
  method: PaymentMethod;
  description: string;
  relatedId?: string;
  date: string;
}

export enum SyncStatus {
  SYNCED = 'Synced',
  SYNCING = 'Syncing',
  OFFLINE = 'Offline',
  ERROR = 'Error'
}

export interface UserSession {
  username: string;
  role: 'Dono' | 'Funcionário' | 'Recepção';
  lastSync: string;
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  shift: string;
  services: number;
  status: 'Ativo' | 'Inativo';
  createdAt: string;
}

export interface Part {
  id: string;
  name: string;
  sku: string;
  costPrice: number;
  salePrice: number;
  stock: number;
  minStock: number;
}

export interface Client {
  id: string;
  name: string;
  phone: string;
  document: string;
  observations: string;
  createdAt: string;
}

export interface Vehicle {
  id: string;
  clientId: string;
  model: string;
  brand: string;
  year: string;
  plate: string;
  km: number;
  observations?: string;
}

export interface OSItem {
  id: string;
  description: string;
  quantity: number;
  unitPrice: number;
  type: 'PART' | 'SERVICE';
}

export interface ServiceOrder {
  id: string;
  osNumber: string;
  clientId: string;
  clientName: string;
  vehicleId: string;
  vehiclePlate: string;
  vehicleModel: string;
  vehicleKm?: string;
  problem: string;
  items: OSItem[];
  laborValue: number;
  discount: number;
  totalValue: number;
  status: OSStatus;
  paymentStatus: PaymentStatus;
  paymentMethod?: PaymentMethod;
  observations?: string;
  dueDate?: string;
  createdAt: string;
  updatedAt: string;
}

export interface VehicleChecklist {
  fuelLevel: string;
  damages: string[];
  items: Record<string, boolean>;
  observations: string;
}

export interface Appointment {
  id: string;
  clientId: string;
  clientName: string;
  vehiclePlate: string;
  serviceType: string;
  date: string;
  time: string;
  status: string;
  attemptsCount: number;
  notes?: string;
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Trash2, Wrench, Package, ChevronLeft, X, Smartphone,
  User, Car, Search, Loader2, Download, DollarSign, Sparkles,
  CreditCard, Wallet, Share2, Printer, CheckCircle2, FileText,
  MessageCircle, Edit3, Save, ArrowRight
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Client, Vehicle, OSItem, OSStatus, ServiceOrder, PaymentStatus, UserSession, PaymentMethod, TransactionType, FinancialTransaction } from '../types';
import html2canvas from 'html2canvas';

const NewServiceOrder: React.FC<{ session?: UserSession; syncData?: (key: string, data: any) => Promise<void> }> = ({ session, syncData }) => {
  const navigate = useNavigate();
  const invoiceRef = useRef<HTMLDivElement>(null);

  // Fluxo de Etapas
  const [step, setStep] = useState<'CLIENT' | 'ITEMS' | 'REVIEW' | 'FINAL'>('CLIENT');

  // Estados de Dados
  const [clients, setClients] = useState<Client[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);

  // Itens da Nota
  const [items, setItems] = useState<OSItem[]>([]);
  const [labor, setLabor] = useState<string>('0');
  const [discount, setDiscount] = useState<string>('0');
  const [km, setKm] = useState('');
  const [obs, setObs] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.PIX);

  const [finalOs, setFinalOs] = useState<ServiceOrder | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (session) {
      const savedClients = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_clients`) || '[]');
      const savedVehicles = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_vehicles`) || '[]');
      setClients(savedClients);
      setVehicles(savedVehicles);
    }
  }, [session]);

  const filteredClients = useMemo(() => {
    if (!clientSearch.trim()) return [];
    return clients.filter(c => 
      c.name.toLowerCase().includes(clientSearch.toLowerCase()) || 
      c.phone.includes(clientSearch)
    );
  }, [clientSearch, clients]);

  const clientVehicles = useMemo(() => {
    return selectedClient ? vehicles.filter(v => v.clientId === selectedClient.id) : [];
  }, [selectedClient, vehicles]);

  const subtotal = useMemo(() => {
    const itemsTotal = items.reduce((acc, curr) => acc + (curr.quantity * curr.unitPrice), 0);
    return itemsTotal + (parseFloat(labor) || 0);
  }, [items, labor]);

  const totalValue = useMemo(() => {
    return Math.max(0, subtotal - (parseFloat(discount) || 0));
  }, [subtotal, discount]);

  const addItem = () => {
    setItems([...items, { id: Math.random().toString(36).substr(2, 9), description: '', quantity: 1, unitPrice: 0, type: 'PART' }]);
  };

  const updateItem = (id: string, field: keyof OSItem, value: any) => {
    setItems(items.map(i => i.id === id ? { ...i, [field]: value } : i));
  };

  const removeItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const handleFinalize = async () => {
    if (!selectedClient || !selectedVehicle || !session || !syncData) {
        alert("Preencha todos os dados obrigatórios (Cliente, Veículo).");
        return;
    }
    setIsSaving(true);

    try {
      const osNumber = `N-${Date.now().toString().slice(-6)}`;
      const osId = Math.random().toString(36).substr(2, 9);

      const os: ServiceOrder = {
        id: osId,
        osNumber,
        clientId: selectedClient.id,
        clientName: selectedClient.name,
        vehicleId: selectedVehicle.id,
        vehiclePlate: selectedVehicle.plate,
        vehicleModel: selectedVehicle.model,
        vehicleKm: km,
        problem: obs || 'Serviço Geral',
        items,
        laborValue: parseFloat(labor) || 0,
        discount: parseFloat(discount) || 0,
        totalValue,
        status: OSStatus.FINALIZADO,
        paymentStatus: PaymentStatus.PAGO,
        paymentMethod,
        observations: obs,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      // Criação automática da transação financeira
      const transaction: FinancialTransaction = {
        id: Math.random().toString(36).substr(2, 9),
        type: TransactionType.INCOME,
        category: 'Serviço/Venda',
        amount: totalValue,
        method: paymentMethod,
        description: `Nota #${osNumber} - ${selectedVehicle.plate}`,
        relatedId: osId,
        date: new Date().toISOString()
      };

      // Busca dados atuais para não sobrescrever
      const currentOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      const currentTransactions = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_transactions`) || '[]');

      // Sincroniza ambos os módulos
      await syncData('orders', [...currentOrders, os]);
      await syncData('transactions', [...currentTransactions, transaction]);

      setFinalOs(os);
      setStep('FINAL');
    } catch (error) {
      console.error(error);
      alert("Erro ao salvar nota. Tente novamente.");
    } finally {
      setIsSaving(false);
    }
  };

  const downloadInvoice = async () => {
    if (!invoiceRef.current) return;
    const canvas = await html2canvas(invoiceRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const link = document.createElement('a');
    link.download = `Nota_${finalOs?.osNumber}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const shareWhatsApp = () => {
    if (!finalOs) return;
    const text = `*COMPROVANTE KAENPRO*\n\nNota: #${finalOs.osNumber}\nCliente: ${finalOs.clientName}\nVeículo: ${finalOs.vehiclePlate}\nValor: R$ ${finalOs.totalValue.toLocaleString('pt-BR')}\n\nObrigado pela preferência!`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  return (
    <div className="flex flex-col h-full bg-[#0B0B0B] text-white overflow-hidden">
      {/* Header Fixo */}
      <div className="p-6 border-b border-zinc-800 flex items-center justify-between sticky top-0 bg-[#0B0B0B] z-20">
        <button onClick={() => navigate(-1)} className="p-2 bg-zinc-900 rounded-xl text-zinc-400 hover:text-white transition-all">
          <ChevronLeft size={20} />
        </button>
        <h2 className="text-sm font-black uppercase tracking-widest italic">Nova <span className="text-[#E11D48]">Nota Pro</span></h2>
        <div className="w-10"></div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar pb-40">
        {step === 'CLIENT' && (
          <div className="space-y-6 animate-in slide-in-from-bottom duration-300">
            <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 shadow-xl">
              <h3 className="text-[10px] font-black uppercase text-zinc-500 mb-6 tracking-widest italic">1. Selecionar Cliente</h3>
              {!selectedClient ? (
                <div className="space-y-4">
                  <div className="relative">
                    <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-zinc-600" size={18} />
                    <input 
                      type="text" value={clientSearch} onChange={(e) => setClientSearch(e.target.value)}
                      placeholder="Pesquisar por Nome ou Tel..."
                      className="w-full bg-zinc-950 border border-zinc-800 rounded-2xl py-5 pl-14 pr-6 text-sm font-bold outline-none focus:border-[#E11D48] transition-all"
                    />
                  </div>
                  <div className="max-h-60 overflow-y-auto space-y-2 no-scrollbar">
                    {filteredClients.map(c => (
                      <button key={c.id} onClick={() => setSelectedClient(c)} className="w-full p-5 bg-zinc-950 rounded-2xl flex items-center justify-between border border-transparent hover:border-[#E11D48] transition-all">
                        <div className="text-left">
                            <span className="font-black text-xs uppercase italic block">{c.name}</span>
                            <span className="text-[9px] text-zinc-600 font-bold tracking-widest">{c.phone}</span>
                        </div>
                        <Plus size={16} className="text-[#E11D48]" />
                      </button>
                    ))}
                    {clientSearch && filteredClients.length === 0 && (
                        <div className="py-10 text-center">
                            <p className="text-zinc-600 font-black uppercase text-[10px] tracking-widest italic">Nenhum cliente sincronizado</p>
                        </div>
                    )}
                  </div>
                </div>
              ) : (
                <div className="flex items-center justify-between bg-zinc-950 p-6 rounded-2xl border border-emerald-500/20 shadow-inner">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500"><User size={20} /></div>
                    <span className="font-black text-xs uppercase italic">{selectedClient.name}</span>
                  </div>
                  <button onClick={() => { setSelectedClient(null); setSelectedVehicle(null); }} className="p-2 text-zinc-600 hover:text-white"><X size={20}/></button>
                </div>
              )}
            </div>

            {selectedClient && (
              <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 animate-in fade-in shadow-xl">
                <h3 className="text-[10px] font-black uppercase text-zinc-500 mb-6 tracking-widest italic">2. Selecionar Veículo</h3>
                <div className="grid grid-cols-2 gap-3">
                  {clientVehicles.map(v => (
                    <button 
                      key={v.id} onClick={() => setSelectedVehicle(v)}
                      className={`p-6 rounded-2xl border-2 transition-all flex flex-col items-center gap-3 ${selectedVehicle?.id === v.id ? 'border-[#E11D48] bg-[#E11D48]/10 text-white shadow-lg' : 'border-zinc-800 bg-zinc-950 text-zinc-600'}`}
                    >
                      <Car size={24} />
                      <span className="font-black text-[10px] tracking-widest uppercase italic">{v.plate}</span>
                    </button>
                  ))}
                  {clientVehicles.length === 0 && (
                      <p className="col-span-2 text-center text-zinc-600 font-bold text-[10px] uppercase italic py-4">Nenhum veículo vinculado a este cliente</p>
                  )}
                </div>
                {selectedVehicle && (
                  <button onClick={() => setStep('ITEMS')} className="w-full mt-8 bg-[#E11D48] py-5 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl glow-red active:scale-95 transition-all">
                    Próximo: Detalhar Nota
                  </button>
                )}
              </div>
            )}
          </div>
        )}

        {step === 'ITEMS' && (
          <div className="space-y-6 animate-in slide-in-from-right duration-300">
            <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 space-y-6 shadow-xl">
              <div className="flex items-center justify-between">
                <h3 className="text-[10px] font-black uppercase text-zinc-500 tracking-widest italic">3. Serviços e Peças</h3>
                <button onClick={addItem} className="p-3 bg-zinc-800 text-[#E11D48] rounded-xl hover:bg-[#E11D48] hover:text-white transition-all shadow-md"><Plus size={18}/></button>
              </div>

              <div className="space-y-4">
                {items.map(item => (
                  <div key={item.id} className="bg-zinc-950 p-5 rounded-[1.5rem] border border-zinc-800 space-y-4 shadow-inner">
                    <input 
                      type="text" placeholder="Descrição do Item..." value={item.description}
                      onChange={(e) => updateItem(item.id, 'description', e.target.value.toUpperCase())}
                      className="w-full bg-transparent border-none text-xs font-black text-white outline-none p-0 placeholder-zinc-800 uppercase italic"
                    />
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-zinc-900 rounded-xl px-3 flex-1 border border-zinc-800/50">
                         <span className="text-[8px] font-black text-zinc-600 uppercase">Qtd</span>
                         <input type="number" value={item.quantity} onChange={(e) => updateItem(item.id, 'quantity', parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-xs font-black py-3 outline-none" />
                      </div>
                      <div className="flex items-center gap-2 bg-zinc-900 rounded-xl px-3 flex-1 border border-zinc-800/50">
                         <span className="text-[8px] font-black text-zinc-600 uppercase">R$</span>
                         <input type="number" value={item.unitPrice} onChange={(e) => updateItem(item.id, 'unitPrice', parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-xs font-black py-3 outline-none" />
                      </div>
                      <button onClick={() => removeItem(item.id)} className="p-3 text-zinc-700 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
                    </div>
                  </div>
                ))}
                {items.length === 0 && <p className="text-center py-6 text-[9px] font-black text-zinc-700 uppercase italic tracking-widest">Nenhum item adicionado à nota</p>}
              </div>
            </div>

            <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 space-y-6 shadow-xl">
              <h3 className="text-[10px] font-black uppercase text-zinc-500 tracking-widest italic">4. Resumo e Pagamento</h3>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[8px] font-black text-zinc-600 uppercase mb-2 block ml-1">Mão de Obra</label>
                  <input type="number" value={labor} onChange={(e) => setLabor(e.target.value)} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-sm font-black text-white shadow-inner" />
                </div>
                <div>
                  <label className="text-[8px] font-black text-zinc-600 uppercase mb-2 block ml-1">Desconto</label>
                  <input type="number" value={discount} onChange={(e) => setDiscount(e.target.value)} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-sm font-black text-[#E11D48] shadow-inner" />
                </div>
              </div>

              <div>
                <label className="text-[8px] font-black text-zinc-600 uppercase mb-2 block ml-1">Forma de Recebimento</label>
                <select 
                  value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value as PaymentMethod)}
                  className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-xs font-black uppercase italic shadow-inner outline-none focus:border-[#E11D48]"
                >
                  {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>

              <div className="p-6 bg-[#E11D48] rounded-[2rem] flex justify-between items-center shadow-xl relative overflow-hidden">
                 <div className="absolute top-0 right-0 p-4 opacity-10"><DollarSign size={40} /></div>
                 <span className="text-[10px] font-black text-white/60 uppercase tracking-widest italic">Total Líquido</span>
                 <span className="text-2xl font-black text-white italic">R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
              </div>

              <button 
                onClick={handleFinalize} disabled={isSaving}
                className="w-full bg-white text-black py-5 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-[#E11D48] hover:text-white transition-all active:scale-95 flex items-center justify-center gap-3"
              >
                {isSaving ? <Loader2 className="animate-spin" size={20}/> : <Save size={20}/>}
                Finalizar Nota e Salvar
              </button>
            </div>
          </div>
        )}

        {step === 'FINAL' && finalOs && (
          <div className="space-y-8 animate-in zoom-in duration-300 flex flex-col items-center">
            {/* NOTA 9:16 PARA COMPARTILHAMENTO PROFISSIONAL */}
            <div 
              ref={invoiceRef}
              className="w-full max-w-[360px] aspect-[9/16] bg-white text-zinc-900 rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col p-8 border-[10px] border-zinc-50"
            >
              <div className="flex justify-between items-start mb-8 border-b-2 border-zinc-100 pb-6">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-zinc-900 rounded-xl flex items-center justify-center text-white"><Wrench size={20}/></div>
                  <h1 className="text-lg font-black tracking-tighter uppercase leading-none italic">KAEN<span className="text-[#E11D48]">PRO</span></h1>
                </div>
                <div className="text-right">
                  <p className="text-[8px] font-black text-zinc-300 uppercase tracking-widest leading-none mb-1">NOTA #{finalOs.osNumber}</p>
                  <p className="text-[9px] font-black text-zinc-900">{new Date(finalOs.createdAt).toLocaleDateString('pt-BR')}</p>
                </div>
              </div>

              <div className="space-y-4 mb-8">
                <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100">
                  <p className="text-[7px] font-black text-zinc-400 uppercase tracking-widest mb-1 italic">Proprietário(a)</p>
                  <p className="text-[11px] font-black uppercase italic">{finalOs.clientName}</p>
                </div>
                <div className="grid grid-cols-2 gap-3">
                   <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100">
                    <p className="text-[7px] font-black text-zinc-400 uppercase tracking-widest mb-1 italic">Veículo</p>
                    <p className="text-[10px] font-black uppercase italic truncate">{finalOs.vehicleModel}</p>
                  </div>
                  <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100">
                    <p className="text-[7px] font-black text-zinc-400 uppercase tracking-widest mb-1 italic">Placa</p>
                    <p className="text-[10px] font-black uppercase italic text-[#E11D48]">{finalOs.vehiclePlate}</p>
                  </div>
                </div>
              </div>

              <div className="flex-1 overflow-hidden">
                <table className="w-full text-left text-[9px]">
                  <thead className="border-b border-zinc-100">
                    <tr className="font-black text-zinc-300 uppercase italic"><th className="pb-2">Descrição do Serviço</th><th className="pb-2 text-right">Valor</th></tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-50 font-bold text-zinc-800">
                    {finalOs.items.map((i,idx)=>(
                      <tr key={idx}><td className="py-3 uppercase italic">{i.description}</td><td className="py-3 text-right font-black italic">R$ {(i.quantity*i.unitPrice).toLocaleString()}</td></tr>
                    ))}
                    {finalOs.laborValue > 0 && (
                      <tr><td className="py-3 font-black uppercase italic">Mão de Obra Especializada</td><td className="py-3 text-right font-black italic">R$ {finalOs.laborValue.toLocaleString()}</td></tr>
                    )}
                  </tbody>
                </table>
              </div>

              <div className="mt-6 pt-6 border-t-2 border-zinc-100">
                <div className="flex justify-between items-center mb-1 text-[8px] opacity-30 uppercase font-black italic">
                  <span>Subtotal Bruto</span>
                  <span>R$ {subtotal.toLocaleString()}</span>
                </div>
                {finalOs.discount > 0 && (
                  <div className="flex justify-between items-center mb-2 text-[8px] text-[#E11D48] font-black uppercase italic">
                    <span>Desconto Aplicado</span>
                    <span>- R$ {finalOs.discount.toLocaleString()}</span>
                  </div>
                )}
                <div className="flex justify-between items-end mt-4">
                   <div className="text-left">
                     <p className="text-[7px] font-black text-zinc-400 uppercase italic mb-1">Pago via</p>
                     <p className="text-[9px] font-black uppercase bg-zinc-900 text-white px-3 py-1 rounded-lg leading-none italic">{finalOs.paymentMethod}</p>
                   </div>
                   <p className="text-3xl font-black italic text-zinc-900 leading-none tracking-tighter">R$ {finalOs.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
              </div>

              <div className="mt-8 text-center">
                 <p className="text-[7px] font-black text-zinc-300 uppercase tracking-[0.4em] italic">Obrigado pela preferência!</p>
              </div>
            </div>

            {/* Ações Mobile */}
            <div className="w-full space-y-4 pt-4">
              <button onClick={shareWhatsApp} className="w-full bg-[#25D366] py-5 rounded-[1.5rem] font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3 shadow-xl shadow-green-900/10 active:scale-95 transition-all">
                <MessageCircle size={22} /> Compartilhar WhatsApp
              </button>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={downloadInvoice} className="bg-zinc-900 py-5 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2 border border-zinc-800 shadow-lg active:scale-95 transition-all">
                  <Download size={18} /> Salvar Imagem
                </button>
                <button onClick={() => window.print()} className="bg-zinc-900 py-5 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2 border border-zinc-800 shadow-lg active:scale-95 transition-all">
                  <Printer size={18} /> Imprimir A4
                </button>
              </div>
              <button onClick={() => navigate('/orders')} className="w-full bg-zinc-800 py-5 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest text-zinc-500 hover:text-white transition-all">
                Ver Histórico de Notas
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default NewServiceOrder;

export enum OSStatus {
  ORCAMENTO = 'Orçamento',
  EM_ANDAMENTO = 'Em Execução',
  FINALIZADO = 'Finalizado',
  CANCELADO = 'Cancelado'
}

export enum PaymentStatus {
  PAGO = 'Pago',
  PENDENTE = 'Pendente',
  ATRASADO = 'Atrasado'
}

export enum TransactionType {
  INCOME = 'INCOME',
  EXPENSE = 'EXPENSE'
}

export enum PaymentMethod {
  PIX = 'PIX',
  DINHEIRO = 'Dinheiro',
  CARTAO_CREDITO = 'Cartão de Crédito',
  CARTAO_DEBITO = 'Cartão de Débito',
  OUTRO = 'Outro'
}

export interface FinancialTransaction {
  id: string;
  type: TransactionType;
  category: string;
  amount: number;
  method: PaymentMethod;
  description: string;
  relatedId?: string;
  date: string;
}

export enum SyncStatus {
  SYNCED = 'Synced',
  SYNCING = 'Syncing',
  OFFLINE = 'Offline',
  ERROR = 'Error'
}

export interface UserSession {
  username: string;
  role: 'Dono' | 'Funcionário' | 'Recepção';
  lastSync: string;
}

export interface Employee {
  id: string;
  name: string;
  role: string;
  shift: string;
  services: number;
  status: 'Ativo' | 'Inativo';
  createdAt: string;
}

export interface Part {
  id: string;
  name: string;
  sku: string;
  costPrice: number;
  salePrice: number;
  stock: number;
  minStock: number;
}

export interface Client {
  id: string;
  name: string;
  phone: string;
  document: string;
  observations: string;
  createdAt: string;
}

export interface Vehicle {
  id: string;
  clientId: string;
  model: string;
  brand: string;
  year: string;
  plate: string;
  km: number;
  observations?: string;
}

export interface OSItem {
  id: string;
  description: string;
  quantity: number;
  unitPrice: number;
  type: 'PART' | 'SERVICE';
}

export interface ServiceOrder {
  id: string;
  osNumber: string;
  clientId: string;
  clientName: string;
  vehicleId: string;
  vehiclePlate: string;
  vehicleModel: string;
  vehicleKm?: string;
  problem: string;
  items: OSItem[];
  laborValue: number;
  discount: number;
  totalValue: number;
  status: OSStatus;
  paymentStatus: PaymentStatus;
  paymentMethod?: PaymentMethod;
  observations?: string;
  dueDate?: string;
  createdAt: string;
  updatedAt: string;
}

export interface VehicleChecklist {
  fuelLevel: string;
  damages: string[];
  items: Record<string, boolean>;
  observations: string;
}

export interface Appointment {
  id: string;
  clientId: string;
  clientName: string;
  vehiclePlate: string;
  serviceType: string;
  date: string;
  time: string;
  status: string;
  attemptsCount: number;
  notes?: string;
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Trash2, Wrench, ChevronLeft, X,
  User, Car, Search, Loader2, Download, DollarSign,
  Printer, Save, MessageCircle, ArrowRight
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Client, Vehicle, OSItem, OSStatus, ServiceOrder, PaymentStatus, UserSession, PaymentMethod, TransactionType, FinancialTransaction } from '../types';
import html2canvas from 'html2canvas';

const NewServiceOrder: React.FC<{ session?: UserSession; syncData?: (key: string, data: any) => Promise<void> }> = ({ session, syncData }) => {
  const navigate = useNavigate();
  const invoiceRef = useRef<HTMLDivElement>(null);

  const [step, setStep] = useState<'CLIENT' | 'ITEMS' | 'FINAL'>('CLIENT');

  const [clients, setClients] = useState<Client[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);

  const [items, setItems] = useState<OSItem[]>([]);
  const [labor, setLabor] = useState<string>('0');
  const [discount, setDiscount] = useState<string>('0');
  const [obs, setObs] = useState('');
  const [paymentMethod, setPaymentMethod] = useState<PaymentMethod>(PaymentMethod.PIX);

  const [finalOs, setFinalOs] = useState<ServiceOrder | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (session) {
      const savedClients = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_clients`) || '[]');
      const savedVehicles = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_vehicles`) || '[]');
      setClients(savedClients);
      setVehicles(savedVehicles);
    }
  }, [session]);

  const filteredClients = useMemo(() => {
    if (!clientSearch.trim()) return [];
    return clients.filter(c => 
      c.name.toLowerCase().includes(clientSearch.toLowerCase()) || 
      c.phone.includes(clientSearch)
    );
  }, [clientSearch, clients]);

  const clientVehicles = useMemo(() => {
    return selectedClient ? vehicles.filter(v => v.clientId === selectedClient.id) : [];
  }, [selectedClient, vehicles]);

  const subtotal = useMemo(() => {
    const itemsTotal = items.reduce((acc, curr) => acc + (curr.quantity * curr.unitPrice), 0);
    return itemsTotal + (parseFloat(labor) || 0);
  }, [items, labor]);

  const totalValue = useMemo(() => {
    return Math.max(0, subtotal - (parseFloat(discount) || 0));
  }, [subtotal, discount]);

  const addItem = () => {
    setItems([...items, { id: Math.random().toString(36).substr(2, 9), description: '', quantity: 1, unitPrice: 0, type: 'PART' }]);
  };

  const updateItem = (id: string, field: keyof OSItem, value: any) => {
    setItems(items.map(i => i.id === id ? { ...i, [field]: value } : i));
  };

  const removeItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const handleFinalize = async () => {
    if (!selectedClient || !selectedVehicle || !session || !syncData) {
      alert("Por favor, selecione um cliente e um veículo.");
      return;
    }

    setIsSaving(true);
    try {
      const osNumber = `NT-${Date.now().toString().slice(-6)}`;
      const osId = Math.random().toString(36).substr(2, 9);

      const os: ServiceOrder = {
        id: osId,
        osNumber,
        clientId: selectedClient.id,
        clientName: selectedClient.name,
        vehicleId: selectedVehicle.id,
        vehiclePlate: selectedVehicle.plate,
        vehicleModel: selectedVehicle.model,
        problem: obs || 'Serviço Geral',
        items,
        laborValue: parseFloat(labor) || 0,
        discount: parseFloat(discount) || 0,
        totalValue,
        status: OSStatus.FINALIZADO,
        paymentStatus: PaymentStatus.PAGO,
        paymentMethod,
        observations: obs,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      const transaction: FinancialTransaction = {
        id: Math.random().toString(36).substr(2, 9),
        type: TransactionType.INCOME,
        category: 'Serviço/Peças',
        amount: totalValue,
        method: paymentMethod,
        description: `Nota #${osNumber} - ${selectedVehicle.plate}`,
        relatedId: osId,
        date: new Date().toISOString()
      };

      const currentOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      const currentTransactions = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_transactions`) || '[]');

      await syncData('orders', [...currentOrders, os]);
      await syncData('transactions', [...currentTransactions, transaction]);

      setFinalOs(os);
      setStep('FINAL');
    } catch (error) {
      console.error(error);
      alert("Erro ao criar nota.");
    } finally {
      setIsSaving(false);
    }
  };

  const downloadInvoice = async () => {
    if (!invoiceRef.current) return;
    const canvas = await html2canvas(invoiceRef.current, { scale: 3, backgroundColor: '#ffffff' });
    const link = document.createElement('a');
    link.download = `Nota_${finalOs?.osNumber}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const shareWhatsApp = () => {
    if (!finalOs) return;
    const text = `*KAENPRO - COMPROVANTE DE SERVIÇO*\n\nNota: #${finalOs.osNumber}\nCliente: ${finalOs.clientName}\nVeículo: ${finalOs.vehiclePlate}\nTotal: R$ ${finalOs.totalValue.toLocaleString('pt-BR')}\n\nObrigado pela preferência!`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  return (
    <div className="flex flex-col h-full bg-[#0B0B0B] text-white overflow-hidden">
      <div className="p-6 border-b border-zinc-800 flex items-center justify-between sticky top-0 bg-[#0B0B0B] z-20">
        <button onClick={() => navigate(-1)} className="p-2 bg-zinc-900 rounded-xl text-zinc-400 hover:text-white transition-all">
          <ChevronLeft size={20} />
        </button>
        <h2 className="text-sm font-black uppercase tracking-widest italic">Nova <span className="text-[#E11D48]">Nota Pro</span></h2>
        <div className="w-10"></div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 space-y-8 no-scrollbar pb-32">
        {step === 'CLIENT' && (
          <div className="space-y-6 animate-in slide-in-from-bottom duration-300">
            <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 shadow-xl">
              <h3 className="text-[10px] font-black uppercase text-zinc-500 mb-6 tracking-widest italic">1. Identificação do Cliente</h3>
              {!selectedClient ? (
                <div className="space-y-4">
                  <div className="relative">
                    <Search className="absolute left-5 top-1/2 -translate-y-1/2 text-zinc-600" size={18} />
                    <input 
                      type="text" value={clientSearch} onChange={(e) => setClientSearch(e.target.value)}
                      placeholder="Pesquisar Nome ou Celular..."
                      className="w-full bg-zinc-950 border border-zinc-800 rounded-2xl py-5 pl-14 pr-6 text-sm font-bold outline-none focus:border-[#E11D48] transition-all"
                    />
                  </div>
                  <div className="max-h-60 overflow-y-auto space-y-2 no-scrollbar">
                    {filteredClients.map(c => (
                      <button key={c.id} onClick={() => setSelectedClient(c)} className="w-full p-5 bg-zinc-950 rounded-2xl flex items-center justify-between border border-transparent hover:border-[#E11D48] transition-all">
                        <div className="text-left">
                            <span className="font-black text-xs uppercase italic block">{c.name}</span>
                            <span className="text-[9px] text-zinc-600 font-bold tracking-widest">{c.phone}</span>
                        </div>
                        <Plus size={16} className="text-[#E11D48]" />
                      </button>
                    ))}
                  </div>
                </div>
              ) : (
                <div className="flex items-center justify-between bg-zinc-950 p-6 rounded-2xl border border-emerald-500/20 shadow-inner">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500"><User size={20} /></div>
                    <span className="font-black text-xs uppercase italic">{selectedClient.name}</span>
                  </div>
                  <button onClick={() => { setSelectedClient(null); setSelectedVehicle(null); }} className="p-2 text-zinc-600 hover:text-white transition-colors"><X size={20}/></button>
                </div>
              )}
            </div>

            {selectedClient && (
              <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 animate-in fade-in shadow-xl">
                <h3 className="text-[10px] font-black uppercase text-zinc-500 mb-6 tracking-widest italic">2. Veículo</h3>
                <div className="grid grid-cols-2 gap-3">
                  {clientVehicles.map(v => (
                    <button 
                      key={v.id} onClick={() => setSelectedVehicle(v)}
                      className={`p-6 rounded-2xl border-2 transition-all flex flex-col items-center gap-3 ${selectedVehicle?.id === v.id ? 'border-[#E11D48] bg-[#E11D48]/10 text-white shadow-lg' : 'border-zinc-800 bg-zinc-950 text-zinc-600'}`}
                    >
                      <Car size={24} />
                      <span className="font-black text-[10px] tracking-widest uppercase italic">{v.plate}</span>
                    </button>
                  ))}
                </div>
                {selectedVehicle && (
                  <button onClick={() => setStep('ITEMS')} className="w-full mt-8 bg-[#E11D48] py-5 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all">
                    Próximo: Itens da Nota
                  </button>
                )}
              </div>
            )}
          </div>
        )}

        {step === 'ITEMS' && (
          <div className="space-y-6 animate-in slide-in-from-right duration-300">
            <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 space-y-6 shadow-xl">
              <div className="flex items-center justify-between">
                <h3 className="text-[10px] font-black uppercase text-zinc-500 tracking-widest italic">3. Serviços e Peças</h3>
                <button onClick={addItem} className="p-3 bg-zinc-800 text-[#E11D48] rounded-xl hover:bg-[#E11D48] hover:text-white transition-all shadow-md"><Plus size={18}/></button>
              </div>

              <div className="space-y-4">
                {items.map(item => (
                  <div key={item.id} className="bg-zinc-950 p-5 rounded-[1.5rem] border border-zinc-800 space-y-4 shadow-inner">
                    <input 
                      type="text" placeholder="Descrição do item..." value={item.description}
                      onChange={(e) => updateItem(item.id, 'description', e.target.value.toUpperCase())}
                      className="w-full bg-transparent border-none text-xs font-black text-white outline-none p-0 placeholder-zinc-800 uppercase italic"
                    />
                    <div className="flex items-center gap-3">
                      <div className="flex items-center gap-2 bg-zinc-900 rounded-xl px-3 flex-1 border border-zinc-800/50">
                         <span className="text-[8px] font-black text-zinc-600 uppercase">Qtd</span>
                         <input type="number" value={item.quantity} onChange={(e) => updateItem(item.id, 'quantity', parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-xs font-black py-3 outline-none" />
                      </div>
                      <div className="flex items-center gap-2 bg-zinc-900 rounded-xl px-3 flex-1 border border-zinc-800/50">
                         <span className="text-[8px] font-black text-zinc-600 uppercase">R$</span>
                         <input type="number" value={item.unitPrice} onChange={(e) => updateItem(item.id, 'unitPrice', parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-xs font-black py-3 outline-none" />
                      </div>
                      <button onClick={() => removeItem(item.id)} className="p-3 text-zinc-700 hover:text-red-500 transition-all"><Trash2 size={18}/></button>
                    </div>
                  </div>
                ))}
              </div>
            </div>

            <div className="bg-zinc-900/50 p-8 rounded-[2.5rem] border border-zinc-800 space-y-6 shadow-xl">
              <h3 className="text-[10px] font-black uppercase text-zinc-500 tracking-widest italic">4. Resumo e Pagamento</h3>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[8px] font-black text-zinc-600 uppercase mb-2 block ml-1">Mão de Obra</label>
                  <input type="number" value={labor} onChange={(e) => setLabor(e.target.value)} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-sm font-black text-white" />
                </div>
                <div>
                  <label className="text-[8px] font-black text-zinc-600 uppercase mb-2 block ml-1">Desconto</label>
                  <input type="number" value={discount} onChange={(e) => setDiscount(e.target.value)} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-sm font-black text-[#E11D48]" />
                </div>
              </div>

              <div>
                <label className="text-[8px] font-black text-zinc-600 uppercase mb-2 block ml-1">Garantia / Obs.</label>
                <textarea 
                  value={obs} onChange={(e) => setObs(e.target.value)}
                  placeholder="Garantia de 90 dias nos serviços..."
                  className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-xs font-bold text-zinc-400 min-h-[100px]"
                />
              </div>

              <div>
                <label className="text-[8px] font-black text-zinc-600 uppercase mb-2 block ml-1">Forma de Pagamento</label>
                <select 
                  value={paymentMethod} onChange={(e) => setPaymentMethod(e.target.value as PaymentMethod)}
                  className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-xs font-black uppercase italic shadow-inner outline-none focus:border-[#E11D48]"
                >
                  {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>

              <div className="p-6 bg-[#E11D48] rounded-[2rem] flex justify-between items-center shadow-xl">
                 <span className="text-[10px] font-black text-white/60 uppercase tracking-widest italic">Total Líquido</span>
                 <span className="text-2xl font-black text-white italic">R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
              </div>

              <button 
                onClick={handleFinalize} disabled={isSaving}
                className="w-full bg-white text-black py-5 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl hover:bg-[#E11D48] hover:text-white transition-all active:scale-95 flex items-center justify-center gap-3"
              >
                {isSaving ? <Loader2 className="animate-spin" size={20}/> : <Save size={20}/>}
                Gerar Nota e Lançar Financeiro
              </button>
            </div>
          </div>
        )}

        {step === 'FINAL' && finalOs && (
          <div className="space-y-8 animate-in zoom-in duration-300 flex flex-col items-center">
            <div 
              ref={invoiceRef}
              className="w-full max-w-[360px] aspect-[9/16] bg-white text-zinc-900 rounded-[2.5rem] overflow-hidden shadow-2xl flex flex-col p-8 border-[10px] border-zinc-50"
            >
              <div className="flex justify-between items-start mb-8 border-b-2 border-zinc-100 pb-6">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-zinc-900 rounded-xl flex items-center justify-center text-white"><Wrench size={20}/></div>
                  <h1 className="text-lg font-black tracking-tighter uppercase leading-none italic">KAEN<span className="text-[#E11D48]">PRO</span></h1>
                </div>
                <div className="text-right">
                  <p className="text-[8px] font-black text-zinc-300 uppercase tracking-widest leading-none mb-1">NOTA #{finalOs.osNumber}</p>
                  <p className="text-[9px] font-black text-zinc-900">{new Date(finalOs.createdAt).toLocaleDateString('pt-BR')}</p>
                </div>
              </div>

              <div className="space-y-4 mb-8">
                <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100">
                  <p className="text-[7px] font-black text-zinc-400 uppercase tracking-widest mb-1 italic">Proprietário(a)</p>
                  <p className="text-[11px] font-black uppercase italic">{finalOs.clientName}</p>
                </div>
                <div className="grid grid-cols-2 gap-3">
                   <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100">
                    <p className="text-[7px] font-black text-zinc-400 uppercase tracking-widest mb-1 italic">Veículo</p>
                    <p className="text-[10px] font-black uppercase italic truncate">{finalOs.vehicleModel}</p>
                  </div>
                  <div className="bg-zinc-50 p-4 rounded-2xl border border-zinc-100">
                    <p className="text-[7px] font-black text-zinc-400 uppercase tracking-widest mb-1 italic">Placa</p>
                    <p className="text-[10px] font-black uppercase italic text-[#E11D48]">{finalOs.vehiclePlate}</p>
                  </div>
                </div>
              </div>

              <div className="flex-1 overflow-hidden">
                <table className="w-full text-left text-[9px]">
                  <thead className="border-b border-zinc-100">
                    <tr className="font-black text-zinc-300 uppercase italic"><th className="pb-2">Serviço/Peça</th><th className="pb-2 text-right">Subtotal</th></tr>
                  </thead>
                  <tbody className="divide-y divide-zinc-50 font-bold text-zinc-800">
                    {finalOs.items.map((i,idx)=>(
                      <tr key={idx}><td className="py-3 uppercase italic">{i.description}</td><td className="py-3 text-right font-black italic">R$ {(i.quantity*i.unitPrice).toLocaleString()}</td></tr>
                    ))}
                    {finalOs.laborValue > 0 && (
                      <tr><td className="py-3 font-black uppercase italic">Mão de Obra</td><td className="py-3 text-right font-black italic">R$ {finalOs.laborValue.toLocaleString()}</td></tr>
                    )}
                  </tbody>
                </table>
              </div>

              <div className="mt-6 pt-6 border-t-2 border-zinc-100">
                <div className="flex justify-between items-center mb-1 text-[8px] opacity-30 uppercase font-black italic">
                  <span>Subtotal</span>
                  <span>R$ {subtotal.toLocaleString()}</span>
                </div>
                {finalOs.discount > 0 && (
                  <div className="flex justify-between items-center mb-2 text-[8px] text-[#E11D48] font-black uppercase italic">
                    <span>Desconto</span>
                    <span>- R$ {finalOs.discount.toLocaleString()}</span>
                  </div>
                )}
                <div className="flex justify-between items-end mt-4">
                   <div className="text-left">
                     <p className="text-[7px] font-black text-zinc-400 uppercase italic mb-1">Pago via</p>
                     <p className="text-[9px] font-black uppercase bg-zinc-900 text-white px-3 py-1 rounded-lg leading-none italic">{finalOs.paymentMethod}</p>
                   </div>
                   <p className="text-3xl font-black italic text-zinc-900 leading-none tracking-tighter">R$ {finalOs.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
                </div>
              </div>

              <div className="mt-6 pt-2">
                 <p className="text-[7px] font-black text-zinc-400 uppercase tracking-widest mb-1 italic">Observações:</p>
                 <p className="text-[8px] text-zinc-600 italic leading-relaxed">{finalOs.observations || 'Nenhuma observação.'}</p>
              </div>

              <div className="mt-8 text-center">
                 <p className="text-[7px] font-black text-zinc-300 uppercase tracking-[0.4em] italic">Obrigado pela preferência!</p>
              </div>
            </div>

            <div className="w-full space-y-4 pt-4">
              <button onClick={shareWhatsApp} className="w-full bg-[#25D366] py-5 rounded-[1.5rem] font-black uppercase text-xs tracking-widest flex items-center justify-center gap-3 shadow-xl active:scale-95 transition-all">
                <MessageCircle size={22} /> Compartilhar WhatsApp
              </button>
              <div className="grid grid-cols-2 gap-4">
                <button onClick={downloadInvoice} className="bg-zinc-900 py-5 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2 border border-zinc-800 shadow-lg active:scale-95 transition-all">
                  <Download size={18} /> Salvar Imagem
                </button>
                <button onClick={() => window.print()} className="bg-zinc-900 py-5 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-2 border border-zinc-800 shadow-lg active:scale-95 transition-all">
                  <Printer size={18} /> Imprimir Nota
                </button>
              </div>
              <button onClick={() => navigate('/orders')} className="w-full bg-zinc-800 py-5 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest text-zinc-500 hover:text-white transition-all">
                Ver Histórico de Notas
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default NewServiceOrder;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  DollarSign, ArrowUpCircle, ArrowDownCircle, PieChart as PieChartIcon, 
  Plus, Search, X, Trash2, Edit3, Loader2, Save, TrendingUp, Filter
} from 'lucide-react';
import { FinancialTransaction, TransactionType, PaymentMethod, UserSession } from '../types';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell,
  PieChart, Pie
} from 'recharts';

const Financial: React.FC<{ session?: UserSession; syncData?: (key: string, data: any) => Promise<void> }> = ({ session, syncData }) => {
  const [transactions, setTransactions] = useState<FinancialTransaction[]>([]);
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const [form, setForm] = useState({
    description: '',
    category: 'Diversos',
    amount: '',
    method: PaymentMethod.PIX,
    type: TransactionType.EXPENSE,
    date: new Date().toISOString().split('T')[0]
  });

  const categories = [
    'Serviço/Peças', 'Aluguel', 'Peças (Compra)', 'Energia/Água', 
    'Internet', 'Salários', 'Impostos', 'Ferramentas', 'Diversos'
  ];

  useEffect(() => {
    if (session) {
      const saved = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_transactions`) || '[]');
      setTransactions(saved);
    }
  }, [session]);

  const handleSave = async () => {
    if (!form.description || !form.amount || !session || !syncData) {
        alert("Preencha Descrição e Valor.");
        return;
    }

    let updated: FinancialTransaction[];
    if (editingId) {
      updated = transactions.map(t => t.id === editingId ? {
        ...t,
        description: form.description,
        category: form.category,
        amount: parseFloat(form.amount),
        method: form.method,
        type: form.type,
        date: new Date(form.date).toISOString()
      } : t);
    } else {
      const newTransaction: FinancialTransaction = {
        id: Math.random().toString(36).substr(2, 9),
        type: form.type,
        category: form.category,
        amount: parseFloat(form.amount),
        method: form.method,
        description: form.description,
        date: new Date(form.date).toISOString()
      };
      updated = [...transactions, newTransaction];
    }

    setTransactions(updated);
    await syncData('transactions', updated);
    setShowModal(false);
    setEditingId(null);
    setForm({ 
        description: '', 
        category: 'Diversos', 
        amount: '', 
        method: PaymentMethod.PIX, 
        type: TransactionType.EXPENSE, 
        date: new Date().toISOString().split('T')[0] 
    });
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Deseja realmente excluir este registro financeiro?")) return;
    const updated = transactions.filter(t => t.id !== id);
    setTransactions(updated);
    await syncData('transactions', updated);
  };

  const handleEdit = (t: FinancialTransaction) => {
    setEditingId(t.id);
    setForm({
      description: t.description,
      category: t.category,
      amount: t.amount.toString(),
      method: t.method,
      type: t.type,
      date: new Date(t.date).toISOString().split('T')[0]
    });
    setShowModal(true);
  };

  const stats = useMemo(() => {
    const todayStr = new Date().toISOString().split('T')[0];
    const income = transactions.filter(t => t.type === TransactionType.INCOME).reduce((a, b) => a + b.amount, 0);
    const expense = transactions.filter(t => t.type === TransactionType.EXPENSE).reduce((a, b) => a + b.amount, 0);
    const dailyIncome = transactions.filter(t => t.type === TransactionType.INCOME && t.date.split('T')[0] === todayStr).reduce((a, b) => a + b.amount, 0);
    const balance = income - expense;

    const chartData = [
      { name: 'Entradas', value: income, fill: '#10B981' },
      { name: 'Saídas', value: expense, fill: '#E11D48' }
    ];

    const categoryDataMap = transactions.reduce((acc, curr) => {
        acc[curr.category] = (acc[curr.category] || 0) + curr.amount;
        return acc;
    }, {} as Record<string, number>);

    const categoryData = Object.keys(categoryDataMap).map(cat => ({
        name: cat,
        value: categoryDataMap[cat]
    }));

    return { income, expense, balance, dailyIncome, chartData, categoryData };
  }, [transactions]);

  const filtered = transactions.filter(t => 
    t.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
    t.category.toLowerCase().includes(searchTerm.toLowerCase())
  ).sort((a,b) => new Date(b.date).getTime() - new Date(a.date).getTime());

  return (
    <div className="space-y-8 animate-in fade-in duration-500 pb-32 h-full overflow-y-auto no-scrollbar scroll-smooth px-6">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-6 mt-6">
        <div>
          <h1 className="text-4xl font-black text-white italic uppercase tracking-tighter">Fluxo de <span className="text-[#E11D48]">Caixa</span></h1>
          <p className="text-zinc-500 font-bold uppercase text-[10px] tracking-[0.2em] italic mt-2">Gestão Financeira Sincronizada</p>
        </div>
        <button 
          onClick={() => setShowModal(true)}
          className="bg-zinc-800 text-white px-8 py-5 rounded-[1.5rem] font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 shadow-xl hover:bg-zinc-700 active:scale-95 transition-all border border-zinc-800"
        >
          <Plus size={20} className="text-[#E11D48]" /> Lançar Despesa / Entrada
        </button>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="bg-[#121214] border border-zinc-800/60 p-8 rounded-[2rem] border-l-4 border-l-emerald-500 shadow-xl">
           <p className="text-zinc-500 text-[9px] font-black uppercase tracking-widest mb-2 italic">Entradas Acumuladas</p>
           <p className="text-3xl font-black text-emerald-500 italic">R$ {stats.income.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-[#121214] border border-zinc-800/60 p-8 rounded-[2rem] border-l-4 border-l-[#E11D48] shadow-xl">
           <p className="text-zinc-500 text-[9px] font-black uppercase tracking-widest mb-2 italic">Saídas Acumuladas</p>
           <p className="text-3xl font-black text-[#E11D48] italic">R$ {stats.expense.toLocaleString('pt-BR')}</p>
        </div>
        <div className="bg-[#121214] border border-zinc-800/60 p-8 rounded-[2rem] border-l-4 border-l-blue-500 shadow-xl">
           <p className="text-zinc-500 text-[9px] font-black uppercase tracking-widest mb-2 italic">Saldo em Caixa</p>
           <p className={`text-3xl font-black italic ${stats.balance >= 0 ? 'text-white' : 'text-[#E11D48]'}`}>
             R$ {stats.balance.toLocaleString('pt-BR')}
           </p>
        </div>
        <div className="bg-zinc-950 border border-zinc-800 p-8 rounded-[2rem] shadow-inner flex flex-col justify-center">
           <p className="text-zinc-600 text-[9px] font-black uppercase tracking-widest mb-2 italic">Faturamento de Hoje</p>
           <p className="text-3xl font-black text-white/50 italic">R$ {stats.dailyIncome.toLocaleString('pt-BR')}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-[#121214] border border-zinc-800/60 p-8 rounded-[2.5rem] shadow-xl h-[350px]">
           <h3 className="text-[10px] font-black uppercase tracking-widest mb-6 italic text-zinc-500 flex items-center gap-2">
             <TrendingUp size={14} /> Balanço de Operação
           </h3>
           <ResponsiveContainer width="100%" height="100%">
             <BarChart data={stats.chartData}>
               <CartesianGrid strokeDasharray="3 3" stroke="#1f1f1f" vertical={false} />
               <XAxis dataKey="name" stroke="#525252" fontSize={10} axisLine={false} tickLine={false} />
               <YAxis hide />
               <Tooltip 
                contentStyle={{ backgroundColor: '#0c0c0e', border: '1px solid #1f1f1f', borderRadius: '12px' }}
                itemStyle={{ fontSize: '10px', fontWeight: 'bold' }}
               />
               <Bar dataKey="value" radius={[10, 10, 0, 0]}>
                 {stats.chartData.map((entry, index) => (
                   <Cell key={`cell-${index}`} fill={entry.fill} />
                 ))}
               </Bar>
             </BarChart>
           </ResponsiveContainer>
        </div>

        <div className="bg-[#121214] border border-zinc-800/60 p-8 rounded-[2.5rem] shadow-xl h-[350px]">
            <h3 className="text-[10px] font-black uppercase tracking-widest mb-6 italic text-zinc-500 flex items-center gap-2">
             <PieChartIcon size={14} /> Despesas por Categoria
           </h3>
           <ResponsiveContainer width="100%" height="100%">
             <PieChart>
               <Pie 
                data={stats.categoryData} 
                cx="50%" cy="50%" 
                innerRadius={60} outerRadius={80} 
                paddingAngle={5} 
                dataKey="value"
               >
                 {stats.categoryData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={['#E11D48', '#10B981', '#3B82F6', '#F59E0B', '#6366F1', '#EC4899'][index % 6]} />
                  ))}
               </Pie>
               <Tooltip 
                 contentStyle={{ backgroundColor: '#0c0c0e', border: '1px solid #1f1f1f', borderRadius: '12px' }}
                 itemStyle={{ fontSize: '10px', fontWeight: 'bold' }}
               />
             </PieChart>
           </ResponsiveContainer>
        </div>
      </div>

      <div className="bg-[#121214] border border-zinc-800/60 rounded-[2.5rem] shadow-2xl overflow-hidden">
        <div className="p-6 border-b border-zinc-800 bg-zinc-950/20 flex items-center gap-4">
           <Search size={22} className="text-zinc-700" />
           <input type="text" value={searchTerm} onChange={(e)=>setSearchTerm(e.target.value)} placeholder="Pesquisar histórico (descrição ou categoria)..." className="bg-transparent border-none text-[11px] font-black uppercase w-full outline-none focus:ring-0 text-white italic tracking-widest"/>
        </div>

        <div className="divide-y divide-zinc-800/50">
           {filtered.map(t => (
             <div key={t.id} className="p-6 flex items-center justify-between gap-6 hover:bg-zinc-800/20 transition-all group">
                <div className="flex items-center gap-5">
                   <div className={`w-14 h-14 rounded-2xl flex items-center justify-center border ${t.type === TransactionType.INCOME ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-500' : 'bg-[#E11D48]/10 border-[#E11D48]/20 text-[#E11D48]'}`}>
                      {t.type === TransactionType.INCOME ? <ArrowUpCircle size={24}/> : <ArrowDownCircle size={24}/>}
                   </div>
                   <div>
                      <p className="text-sm font-black text-white uppercase italic tracking-tight truncate max-w-[200px]">{t.description}</p>
                      <p className="text-[10px] font-bold text-zinc-600 uppercase tracking-widest mt-1 italic">
                        {new Date(t.date).toLocaleDateString('pt-BR')} • {t.category}
                      </p>
                   </div>
                </div>

                <div className="flex items-center gap-10">
                   <div className="text-right">
                      <p className={`text-xl font-black italic ${t.type === TransactionType.INCOME ? 'text-emerald-500' : 'text-[#E11D48]'}`}>
                        {t.type === TransactionType.INCOME ? '+' : '-'} R$ {t.amount.toLocaleString('pt-BR')}
                      </p>
                      <p className="text-[9px] font-bold text-zinc-700 uppercase tracking-widest italic">{t.method}</p>
                   </div>
                   <div className="flex gap-2">
                      <button onClick={()=>handleEdit(t)} className="p-3 bg-zinc-900 text-zinc-500 hover:text-white rounded-xl border border-zinc-800 shadow-md transition-all"><Edit3 size={18}/></button>
                      <button onClick={()=>handleDelete(t.id)} className="p-3 bg-zinc-900 text-zinc-500 hover:text-red-500 rounded-xl border border-zinc-800 shadow-md transition-all"><Trash2 size={18}/></button>
                   </div>
                </div>
             </div>
           ))}
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/95 backdrop-blur-md">
           <div className="bg-[#0c0c0e] border border-zinc-800 w-full max-w-lg p-10 rounded-[3rem] shadow-2xl relative animate-in zoom-in duration-300">
              <button onClick={() => { setShowModal(false); setEditingId(null); }} className="absolute top-8 right-8 text-zinc-500 hover:text-white transition-all"><X size={28} /></button>
              <h2 className="text-2xl font-black text-white italic uppercase tracking-tighter mb-10">{editingId ? 'Editar Movimentação' : 'Novo Lançamento'}</h2>
              <div className="space-y-6">
                <div className="flex gap-2 p-1.5 bg-zinc-950 rounded-2xl border border-zinc-800 shadow-inner">
                  <button onClick={()=>setForm({...form, type: TransactionType.INCOME})} className={`flex-1 py-4 rounded-xl font-black text-[10px] uppercase transition-all italic tracking-widest ${form.type === TransactionType.INCOME ? 'bg-emerald-500 text-white shadow-lg' : 'text-zinc-600'}`}>Entrada</button>
                  <button onClick={()=>setForm({...form, type: TransactionType.EXPENSE})} className={`flex-1 py-4 rounded-xl font-black text-[10px] uppercase transition-all italic tracking-widest ${form.type === TransactionType.EXPENSE ? 'bg-[#E11D48] text-white shadow-lg' : 'text-zinc-600'}`}>Saída (Despesa)</button>
                </div>
                <div>
                  <label className="text-[10px] font-black text-zinc-600 uppercase mb-2 block ml-1 italic tracking-widest">Descrição</label>
                  <input type="text" value={form.description} onChange={(e)=>setForm({...form, description: e.target.value.toUpperCase()})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-white font-bold text-sm outline-none focus:border-[#E11D48]"/>
                </div>
                <div className="grid grid-cols-2 gap-4">
                   <div>
                    <label className="text-[10px] font-black text-zinc-600 uppercase mb-2 block ml-1 italic tracking-widest">Valor (R$)</label>
                    <input type="number" value={form.amount} onChange={(e)=>setForm({...form, amount: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-white font-black text-lg outline-none focus:border-[#E11D48]"/>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-zinc-600 uppercase mb-2 block ml-1 italic tracking-widest">Data</label>
                    <input type="date" value={form.date} onChange={(e)=>setForm({...form, date: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-white font-black text-[10px] outline-none focus:border-[#E11D48]"/>
                  </div>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[10px] font-black text-zinc-600 uppercase mb-2 block ml-1 italic tracking-widest">Categoria</label>
                    <select value={form.category} onChange={(e)=>setForm({...form, category: e.target.value})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-white font-bold text-xs outline-none focus:border-[#E11D48]">
                       {categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div>
                    <label className="text-[10px] font-black text-zinc-600 uppercase mb-2 block ml-1 italic tracking-widest">Método</label>
                    <select value={form.method} onChange={(e)=>setForm({...form, method: e.target.value as PaymentMethod})} className="w-full bg-zinc-950 border border-zinc-800 rounded-xl px-4 py-4 text-white font-bold text-xs outline-none focus:border-[#E11D48]">
                       {Object.values(PaymentMethod).map(m => <option key={m} value={m}>{m}</option>)}
                    </select>
                  </div>
                </div>
                <button onClick={handleSave} className="w-full bg-[#E11D48] py-5 rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl mt-4 active:scale-95 transition-all">
                  Confirmar Registro Financeiro
                </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

