                        {[...Array(Math.max(0, 5 - finalOs.items.length))].map((_, i) => (
                           <tr key={`empty-${i}`}><td className="py-4">&nbsp;</td><td className="py-4">&nbsp;</td><td className="py-4">&nbsp;</td><td className="py-4">&nbsp;</td></tr>
                        ))}
