                <div className={`text-[8px] font-black uppercase inline-block px-2 py-0.5 rounded mt-1 ${os.paymentStatus === PaymentStatus.PAGO ? 'bg-emerald-500/10 text-emerald-500' : 'bg-amber-500/10 text-amber-500'}`}>
