                          PAGAMENTO: {finalOs.paymentStatus}
                       </div>
                       <div className="w-64 pt-4 border-t border-zinc-200">
                          <p className="text-[8px] font-black text-zinc-300 uppercase text-center tracking-widest">ASSINATURA DO RESPONSÁVEL</p>
