                      </div>
                    </div>
                  </div>

                  {/* Adaptive Data Table */}
                  <div className="flex-1 mb-8">
                     <table className="w-full text-left border-collapse">
                        <thead>
                          <tr className="text-[8px] font-black text-zinc-200 uppercase tracking-[0.4em] border-b border-zinc-50">
