import React, { useState, useEffect } from 'react';
import { 
  DollarSign, 
  Car, 
  Package, 
  PlusCircle, 
  Sparkles,
  Loader2,
  Calendar,
  ArrowUpRight
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { ServiceOrder, Part, OSStatus, UserSession } from '../types';
import { GoogleGenAI } from "@google/genai";

const Dashboard: React.FC<{ session?: UserSession }> = ({ session }) => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<ServiceOrder[]>([]);
  const [parts, setParts] = useState<Part[]>([]);
  const [aiInsight, setAiInsight] = useState<string>('');
  const [isAiLoading, setIsAiLoading] = useState(false);

  useEffect(() => {
    if (session) {
      const savedOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      const savedParts = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_parts`) || '[]');
      setOrders(savedOrders);
      setParts(savedParts);
      fetchAiInsights(savedOrders, savedParts);
    }
  }, [session]);

  const fetchAiInsights = async (currentOrders: ServiceOrder[], currentParts: Part[]) => {
    if (!process.env.API_KEY) {
      setAiInsight('Inteligência: Giro de estoque dinâmico necessário para maximizar o faturamento hoje.');
      return;
    }

    setIsAiLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const prompt = `Analise os dados desta oficina mecânica: ${currentOrders.length} ordens de serviço e ${currentParts.length} itens no estoque. Forneça um insight estratégico de 2 frases para o dono da oficina aumentar o lucro hoje em estilo executivo Apple. Em português.`;
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
      });
      setAiInsight(response.text || 'Sinergia operacional detectada. Foco total em ordens de serviço pendentes.');
    } catch (err) {
      setAiInsight('Alerta de Otimização: Peças de alta velocidade requerem auditoria imediata para pico de demanda.');
    } finally {
      setIsAiLoading(false);
    }
  };

  const dailyFinished = orders.filter(o => new Date(o.updatedAt).toDateString() === new Date().toDateString() && o.status === OSStatus.FINALIZADO);
  const dailyRevenue = dailyFinished.reduce((acc, curr) => acc + curr.totalValue, 0);
  const criticalStock = parts.filter(p => p.stock <= p.minStock).length;

  return (
    <div className="space-y-12 animate-ios-slide p-6 md:p-12 pb-32 max-w-[1400px] mx-auto">
      <div className="flex flex-col md:flex-row md:items-end justify-between gap-8">
        <div className="animate-in fade-in slide-in-from-left duration-1000">
          <h1 className="text-5xl md:text-8xl font-black text-white italic uppercase tracking-tighter leading-none">
            Sinergia <span className="text-[#FF2D55]">Central</span>
          </h1>
          <p className="text-zinc-500 font-bold text-[10px] uppercase tracking-[0.4em] flex items-center gap-3 mt-6">
            <Calendar size={14} className="text-[#FF2D55]" /> Painel Neural • v 26.0
          </p>
        </div>
        <button 
          onClick={() => navigate('/orders/new')} 
          className="bg-[#FF2D55] text-white px-10 py-6 rounded-ios font-black uppercase text-[11px] tracking-[0.3em] flex items-center gap-4 shadow-2xl shadow-[#FF2D55]/30 hover:scale-105 active:scale-95 transition-all"
        >
          <PlusCircle size={20} /> Lançar Nova Nota
        </button>
      </div>

      {/* CARD DE INSIGHT IA */}
      <div className="glass-card p-12 rounded-ios relative overflow-hidden group border-white/10 hover:border-[#FF2D55]/30 transition-all duration-700">
        <div className="absolute -top-20 -right-20 p-20 text-[#FF2D55]/10 opacity-20 group-hover:scale-125 transition-transform duration-1000">
          <Sparkles size={280}/>
        </div>
        <div className="flex items-center gap-4 mb-8">
          <div className="p-4 bg-white/5 rounded-2xl border border-white/10">
            <Sparkles size={24} className="text-[#FF2D55] animate-pulse"/>
          </div>
          <h3 className="text-[11px] font-black text-zinc-400 uppercase tracking-[0.5em] italic">Inteligência Bionic</h3>
        </div>
        {isAiLoading ? (
          <div className="flex items-center gap-4 text-zinc-600 italic">
            <Loader2 className="animate-spin" size={24}/> 
            <span className="text-lg font-black uppercase tracking-widest">Sintetizando telemetria...</span>
          </div>
        ) : (
          <p className="text-2xl md:text-4xl font-black text-white italic leading-[1.2] max-w-5xl tracking-tight">
            {aiInsight || 'Link estabelecido. Aguardando fluxo de dados...'}
          </p>
        )}
      </div>

      {/* TILES DE ESTATÍSTICAS */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
        <div className="glass-card p-10 rounded-ios hover-lift group relative overflow-hidden shadow-2xl shadow-black">
          <div className="flex justify-between items-start mb-8">
            <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em]">Volume Diário</p>
            <ArrowUpRight size={22} className="text-emerald-500 group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
          </div>
          <p className="text-4xl font-black text-white italic tracking-tighter">
            R$ {dailyRevenue.toLocaleString('pt-BR')}
          </p>
          <div className="mt-8 h-[2px] bg-white/5 rounded-full overflow-hidden">
            <div className="h-full bg-emerald-500 w-[72%] shadow-[0_0_15px_#10B981]"></div>
          </div>
        </div>

        <div className="glass-card p-10 rounded-ios hover-lift shadow-2xl shadow-black">
          <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mb-8">Handover Neural</p>
          <p className="text-5xl font-black text-white italic tracking-tighter">{dailyFinished.length}</p>
          <p className="text-[10px] text-zinc-600 font-bold uppercase mt-6 tracking-widest">Serviços Finalizados</p>
        </div>

        <div className="glass-card p-10 rounded-ios hover-lift shadow-2xl shadow-black">
          <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mb-8">Telemetria Ativa</p>
          <p className="text-5xl font-black text-white italic tracking-tighter">
            {orders.filter(o => o.status === OSStatus.EM_ANDAMENTO).length}
          </p>
          <p className="text-[10px] text-zinc-600 font-bold uppercase mt-6 tracking-widest">Em Execução</p>
        </div>

        <div className="glass-card p-10 rounded-ios hover-lift border-[#FF2D55]/10 hover:border-[#FF2D55]/50 shadow-2xl shadow-black">
          <p className="text-zinc-500 text-[10px] font-black uppercase tracking-[0.3em] mb-8">Insumos Críticos</p>
          <p className={`text-5xl font-black italic tracking-tighter ${criticalStock > 0 ? 'text-[#FF2D55]' : 'text-white'}`}>
            {criticalStock}
          </p>
          <p className="text-[10px] text-zinc-600 font-bold uppercase mt-6 tracking-widest">Abaixo do Mínimo</p>
        </div>
      </div>
    </div>
  );
};

