import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Trash2, Wrench, ChevronLeft, ChevronRight, X,
  User, Car, Search, Loader2, Download, 
  Printer, Save, MessageCircle, Check, ImageIcon
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Client, Vehicle, OSItem, OSStatus, ServiceOrder, PaymentStatus, UserSession } from '../types';
import html2canvas from 'html2canvas';

const NewServiceOrder: React.FC<{ session?: UserSession; syncData?: (key: string, data: any) => Promise<void> }> = ({ session, syncData }) => {
  const navigate = useNavigate();
  const invoiceRef = useRef<HTMLDivElement>(null);

  const [step, setStep] = useState<'CLIENTE' | 'ITENS' | 'FINAL'>('CLIENTE');

  const [clients, setClients] = useState<Client[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);

  const [items, setItems] = useState<OSItem[]>([]);
  const [labor, setLabor] = useState<string>('0');
  const [discount, setDiscount] = useState<string>('0');
  const [obs, setObs] = useState('');
  const [paymentStatus, setPaymentStatus] = useState<PaymentStatus>(PaymentStatus.PENDENTE);

  const [finalOs, setFinalOs] = useState<ServiceOrder | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (session) {
      const savedClients = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_clients`) || '[]');
      const savedVehicles = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_vehicles`) || '[]');
      setClients(savedClients);
      setVehicles(savedVehicles);
    }
  }, [session]);

  const filteredClients = useMemo(() => {
    if (!clientSearch.trim()) return [];
    return clients.filter(c => 
      c.name.toLowerCase().includes(clientSearch.toLowerCase()) || 
      c.phone.includes(clientSearch)
    );
  }, [clientSearch, clients]);

  const clientVehicles = useMemo(() => {
    return selectedClient ? vehicles.filter(v => v.clientId === selectedClient.id) : [];
  }, [selectedClient, vehicles]);

  const subtotal = useMemo(() => {
    const itemsTotal = items.reduce((acc, curr) => acc + (curr.quantity * curr.unitPrice), 0);
    return itemsTotal + (parseFloat(labor) || 0);
  }, [items, labor]);

  const totalValue = useMemo(() => {
    return Math.max(0, subtotal - (parseFloat(discount) || 0));
  }, [subtotal, discount]);

  const addItem = () => {
    setItems([...items, { id: Math.random().toString(36).substr(2, 9), description: '', quantity: 1, unitPrice: 0, type: 'SERVICE' }]);
  };

  const updateItem = (id: string, field: keyof OSItem, value: any) => {
    setItems(items.map(i => i.id === id ? { ...i, [field]: value } : i));
  };

  const removeItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const handleFinalize = async () => {
    if (!selectedClient || !selectedVehicle || !session || !syncData) {
      alert("Selecione cliente e veículo para continuar.");
      return;
    }

    setIsSaving(true);
    try {
      const osNumber = `KP-${Math.floor(100000 + Math.random() * 900000)}`;
      const osId = Math.random().toString(36).substr(2, 9);

      const os: ServiceOrder = {
        id: osId,
        osNumber,
        clientId: selectedClient.id,
        clientName: selectedClient.name,
        vehicleId: selectedVehicle.id,
        vehiclePlate: selectedVehicle.plate,
        vehicleModel: selectedVehicle.model,
        vehicleKm: selectedVehicle.km.toString(),
        problem: obs || 'Serviços Automotivos',
        items,
        laborValue: parseFloat(labor) || 0,
        discount: parseFloat(discount) || 0,
        totalValue,
        status: OSStatus.FINALIZADO,
        paymentStatus,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      const currentOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      await syncData('orders', [...currentOrders, os]);

      setFinalOs(os);
      setStep('FINAL');
    } catch (error) {
      alert("Erro ao salvar dados.");
    } finally {
      setIsSaving(false);
    }
  };

  const downloadImage = async () => {
    if (!invoiceRef.current) return;
    const canvas = await html2canvas(invoiceRef.current, { 
      scale: 3, 
      backgroundColor: '#ffffff',
      windowWidth: 800
    });
    const link = document.createElement('a');
    link.download = `Nota_Kaen_${finalOs?.osNumber}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const handleWhatsApp = () => {
    if (!finalOs) return;
    const text = `*KAEN MECÂNICA - COMPROVANTE*\n\nNota: #${finalOs.osNumber}\nVeículo: ${finalOs.vehiclePlate}\nTotal: R$ ${finalOs.totalValue.toLocaleString('pt-BR')}\nStatus: ${finalOs.paymentStatus === PaymentStatus.PAGO ? 'Pago' : 'Pendente'}\n\nObrigado pela confiança!`;
    window.open(`https://wa.me/?text=${encodeURIComponent(text)}`, '_blank');
  };

  // Escala dinâmica para a nota
  const isCompact = items.length > 8;
  const itemFontSize = isCompact ? 'text-[9px]' : 'text-[11px]';
  const itemPadding = isCompact ? 'py-1.5' : 'py-3';

  return (
    <div className="flex flex-col h-full bg-[#000000] text-white selection:bg-[#FF2D55]">
      {/* Header Mobile Bionic */}
      <div className="p-8 border-b border-white/5 flex items-center justify-between glass-card sticky top-0 z-50 print:hidden">
        <button onClick={() => navigate(-1)} className="p-4 bg-white/5 rounded-full text-zinc-400 active:scale-90 transition-transform border border-white/10">
          <ChevronLeft size={20} />
        </button>
        <h2 className="text-[11px] font-black uppercase tracking-[0.5em] italic">Nova <span className="text-[#FF2D55]">Nota Bionic</span></h2>
        <div className="w-12"></div>
      </div>

      <div className="flex-1 overflow-y-auto p-4 sm:p-10 no-scrollbar print:p-0 print:overflow-visible scroll-smooth">
        {step !== 'FINAL' ? (
          <div className="max-w-2xl mx-auto space-y-10 animate-ios-slide pb-32">
            {/* Step 1: Identificação */}
            <div className="glass-card p-10 rounded-ios border border-white/10 space-y-8 shadow-2xl">
               <div className="flex items-center gap-4">
                 <div className="w-10 h-10 bg-[#FF2D55]/10 rounded-2xl flex items-center justify-center text-[#FF2D55] border border-[#FF2D55]/20"><User size={20}/></div>
                 <h3 className="text-[11px] font-black uppercase text-zinc-400 tracking-[0.4em] italic">Identidade de Unidade</h3>
               </div>

               {!selectedClient ? (
                  <div className="relative group">
                    <Search className="absolute left-8 top-1/2 -translate-y-1/2 text-zinc-700 group-focus-within:text-[#FF2D55] transition-colors" size={24} />
                    <input 
                      type="text" value={clientSearch} onChange={(e) => setClientSearch(e.target.value)}
                      placeholder="Buscar Proprietário..."
                      className="w-full bg-black/50 border-2 border-white/5 rounded-[2rem] py-8 pl-20 pr-8 text-sm font-black outline-none focus:border-[#FF2D55]/40 transition-all placeholder-zinc-800"
                    />
                    {filteredClients.length > 0 && (
                       <div className="mt-4 space-y-2 max-h-64 overflow-y-auto no-scrollbar animate-in fade-in slide-in-from-top-4">
                         {filteredClients.map(c => (
                           <button key={c.id} onClick={() => setSelectedClient(c)} className="w-full p-6 bg-white/5 hover:bg-[#FF2D55] rounded-[2rem] flex items-center justify-between border border-white/5 transition-all group">
                             <span className="text-xs font-black uppercase italic group-hover:text-white tracking-widest">{c.name}</span>
                             <Plus size={18} className="text-[#FF2D55] group-hover:text-white" />
                           </button>
                         ))}
                       </div>
                    )}
                  </div>
               ) : (
                  <div className="bg-white/5 p-8 rounded-ios border border-[#FF2D55]/20 flex justify-between items-center animate-in zoom-in">
                    <div className="flex flex-col">
                      <span className="text-[9px] font-black text-zinc-600 uppercase tracking-widest mb-2">Proprietário Ativo</span>
                      <span className="text-lg font-black uppercase italic text-white tracking-tighter">{selectedClient.name}</span>
                    </div>
                    <button onClick={() => {setSelectedClient(null); setSelectedVehicle(null);}} className="p-3 bg-white/5 rounded-full text-zinc-500 hover:text-white transition-all"><X size={24}/></button>
                  </div>
               )}

               {selectedClient && !selectedVehicle && (
                  <div className="grid grid-cols-1 gap-4 animate-in slide-in-from-bottom-6">
                    {clientVehicles.map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v)} className="p-8 bg-white/5 border border-white/5 rounded-ios text-left hover:border-[#FF2D55]/50 transition-all group shadow-xl">
                        <div className="flex items-center justify-between">
                          <div className="flex flex-col">
                            <span className="text-2xl font-black text-white group-hover:text-[#FF2D55] transition-colors italic tracking-tighter">{v.plate}</span>
                            <span className="text-[10px] font-bold text-zinc-500 uppercase tracking-widest mt-1">{v.model}</span>
                          </div>
                          <ChevronRight size={24} className="text-zinc-800 group-hover:text-[#FF2D55]"/>
                        </div>
                      </button>
                    ))}
                  </div>
               )}

               {selectedVehicle && (
                 <div className="bg-white/5 p-8 rounded-ios border border-white/5 flex justify-between items-center animate-in zoom-in shadow-inner">
                    <div className="flex flex-col">
                      <span className="text-[9px] font-black text-zinc-600 uppercase tracking-widest mb-2">Veículo Alvo</span>
                      <span className="text-lg font-black uppercase italic text-[#FF2D55] tracking-tighter">{selectedVehicle.plate} • {selectedVehicle.model}</span>
                    </div>
                    <button onClick={() => setSelectedVehicle(null)} className="p-3 bg-white/5 rounded-full text-zinc-500 hover:text-white"><X size={22}/></button>
                 </div>
               )}
            </div>

            {/* Step 2: Itens */}
            {selectedVehicle && (
               <div className="glass-card p-10 rounded-ios border border-white/10 space-y-10 shadow-2xl animate-in slide-in-from-bottom-10">
                  <div className="flex justify-between items-center">
                    <div className="flex items-center gap-4">
                      <div className="w-10 h-10 bg-[#FF2D55]/10 rounded-2xl flex items-center justify-center text-[#FF2D55] border border-[#FF2D55]/20"><Wrench size={20}/></div>
                      <h3 className="text-[11px] font-black uppercase text-zinc-400 tracking-[0.4em] italic">Serviços e Peças</h3>
                    </div>
                    <button onClick={addItem} className="p-5 bg-[#FF2D55] rounded-2xl text-white shadow-xl hover:scale-110 active:scale-90 transition-all"><Plus size={24}/></button>
                  </div>

                  <div className="space-y-4">
                    {items.map(item => (
                      <div key={item.id} className="bg-black/50 p-6 rounded-[2.5rem] border border-white/5 space-y-5 hover:border-white/10 transition-all group">
                        <input 
                          type="text" placeholder="DESCRIÇÃO DO ITEM..." 
                          value={item.description} 
                          onChange={(e)=>updateItem(item.id, 'description', e.target.value.toUpperCase())} 
                          className="w-full bg-transparent text-[11px] font-black outline-none uppercase italic text-white placeholder-zinc-800 tracking-widest"
                        />
                        <div className="flex gap-4">
                           <div className="flex-1 flex bg-black/60 p-1.5 rounded-2xl border border-white/5">
                             <input type="number" placeholder="Qtd" value={item.quantity} onChange={(e)=>updateItem(item.id, 'quantity', parseFloat(e.target.value) || 0)} className="w-full bg-transparent p-4 text-center text-xs font-black text-white outline-none"/>
                           </div>
                           <div className="flex-[2] flex bg-black/60 p-1.5 rounded-2xl border border-white/5">
                             <span className="flex items-center pl-5 text-zinc-700 text-[10px] font-black italic tracking-widest">R$</span>
                             <input type="number" placeholder="0,00" value={item.unitPrice} onChange={(e)=>updateItem(item.id, 'unitPrice', parseFloat(e.target.value) || 0)} className="w-full bg-transparent p-4 text-xs font-black text-white outline-none"/>
                           </div>
                           <button onClick={()=>removeItem(item.id)} className="p-4 text-zinc-800 hover:text-[#FF2D55] transition-colors"><Trash2 size={24}/></button>
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className="grid grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <label className="text-[10px] font-black uppercase text-zinc-700 tracking-widest ml-4 italic">Mão de Obra</label>
                      <input type="number" value={labor} onChange={(e)=>setLabor(e.target.value)} className="w-full bg-black/60 border border-white/5 p-6 rounded-[2rem] text-sm font-black outline-none focus:border-[#FF2D55] shadow-inner"/>
                    </div>
                    <div className="space-y-4">
                      <label className="text-[10px] font-black uppercase text-zinc-700 tracking-widest ml-4 italic">Liquidação</label>
                      <select value={paymentStatus} onChange={(e)=>setPaymentStatus(e.target.value as PaymentStatus)} className="w-full bg-black/60 border border-white/5 p-6 rounded-[2rem] text-[10px] font-black uppercase outline-none focus:border-[#FF2D55] shadow-inner">
                        <option value={PaymentStatus.PENDENTE}>Aguardando Pix</option>
                        <option value={PaymentStatus.PAGO}>Confirmado</option>
                      </select>
                    </div>
                  </div>

                  <div className="p-10 bg-[#FF2D55]/5 rounded-ios border border-[#FF2D55]/10 flex flex-col items-center gap-2 shadow-inner">
                    <span className="text-[10px] font-black uppercase text-zinc-600 tracking-[0.5em]">Montante Neural</span>
                    <span className="text-5xl font-black text-white italic tracking-tighter">R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
                  </div>

                  <button 
