          </p>
        </div>
        <button 
          onClick={() => navigate('/orders/new')} 
          className="bg-[#FF2D55] text-white w-full md:w-auto px-16 py-7 rounded-ios font-black uppercase text-[12px] tracking-[0.4em] flex items-center justify-center gap-5 shadow-2xl shadow-[#FF2D55]/30 hover:scale-[1.03] active:scale-95 transition-all"
        >
          <PlusCircle size={24} /> Lançar Nova Nota
        </button>
      </div>

      {/* CARD DE INSIGHT IA CENTRALIZADO */}
      <div className="w-full glass-card p-12 rounded-ios relative overflow-hidden group border-white/10 hover:border-[#FF2D55]/30 transition-all duration-700 shadow-3xl text-center flex flex-col items-center">
        <div className="absolute -top-20 -right-20 p-20 text-[#FF2D55]/10 opacity-10 group-hover:scale-125 transition-transform duration-1000 pointer-events-none">
          <Sparkles size={300}/>
        </div>
        <div className="flex flex-col items-center gap-6 mb-10">
          <div className="p-5 bg-white/5 rounded-3xl border border-white/10 shadow-inner">
            <Sparkles size={32} className="text-[#FF2D55] animate-pulse"/>
          </div>
          <h3 className="text-[11px] font-black text-zinc-500 uppercase tracking-[0.7em] italic">Análise de Inteligência</h3>
        </div>
        {isAiLoading ? (
          <div className="flex flex-col items-center gap-6 text-zinc-600 italic">
            <Loader2 className="animate-spin" size={32}/> 
            <span className="text-lg font-black uppercase tracking-[0.3em]">Sintetizando Telemetria...</span>
          </div>
        ) : (
          <p className="text-2xl md:text-5xl font-black text-white italic leading-[1.1] max-w-5xl tracking-tighter">
