import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Trash2, Wrench, ChevronLeft, X,
  User, Search, Loader2, Check, ImageIcon, MessageCircle, CreditCard
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Client, Vehicle, OSItem, OSStatus, ServiceOrder, PaymentStatus, UserSession } from '../types';
import html2canvas from 'html2canvas';

const NewServiceOrder: React.FC<{ session?: UserSession; syncData?: (key: string, data: any) => Promise<void> }> = ({ session, syncData }) => {
  const navigate = useNavigate();
  const invoiceRef = useRef<HTMLDivElement>(null);

  const [step, setStep] = useState<'CLIENTE' | 'ITENS' | 'FINAL'>('CLIENTE');
  const [clients, setClients] = useState<Client[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [clientSearch, setClientSearch] = useState('');
  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);

  const [items, setItems] = useState<OSItem[]>([]);
  const [labor, setLabor] = useState<string>('0');
  const [discount, setDiscount] = useState<string>('0');
  const [paymentStatus, setPaymentStatus] = useState<PaymentStatus>(PaymentStatus.PENDENTE);

  const [finalOs, setFinalOs] = useState<ServiceOrder | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (session) {
      const savedClients = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_clients`) || '[]');
      const savedVehicles = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_vehicles`) || '[]');
      setClients(savedClients);
      setVehicles(savedVehicles);
    }
  }, [session]);

  const filteredClients = useMemo(() => {
    if (!clientSearch.trim()) return [];
    return clients.filter(c => 
      c.name.toLowerCase().includes(clientSearch.toLowerCase()) || 
      c.phone.includes(clientSearch)
    );
  }, [clientSearch, clients]);

  const clientVehicles = useMemo(() => {
    return selectedClient ? vehicles.filter(v => v.clientId === selectedClient.id) : [];
  }, [selectedClient, vehicles]);

  const totalValue = useMemo(() => {
    const itemsTotal = items.reduce((acc, curr) => acc + (curr.quantity * curr.unitPrice), 0);
    const subtotal = itemsTotal + (parseFloat(labor) || 0);
    return Math.max(0, subtotal - (parseFloat(discount) || 0));
  }, [items, labor, discount]);

  const addItem = () => {
    setItems([...items, { id: Math.random().toString(36).substr(2, 9), description: '', quantity: 1, unitPrice: 0, type: 'SERVICE' }]);
  };

  const updateItem = (id: string, field: keyof OSItem, value: any) => {
    setItems(items.map(i => i.id === id ? { ...i, [field]: value } : i));
  };

  const removeItem = (id: string) => {
    setItems(items.filter(i => i.id !== id));
  };

  const handleFinalize = async () => {
    if (!selectedClient || !selectedVehicle || !session || !syncData) return;

    setIsSaving(true);
    try {
      const osNumber = `${Math.floor(1000 + Math.random() * 9000)}`;
      const osId = Math.random().toString(36).substr(2, 9);

      const os: ServiceOrder = {
        id: osId,
        osNumber,
        clientId: selectedClient.id,
        clientName: selectedClient.name,
        vehicleId: selectedVehicle.id,
        vehiclePlate: selectedVehicle.plate,
        vehicleModel: selectedVehicle.model,
        vehicleKm: selectedVehicle.km.toString(),
        problem: 'SISTEMA KAENPRO: MANUTENÇÃO DE ALTA PRECISÃO',
        items,
        laborValue: parseFloat(labor) || 0,
        discount: parseFloat(discount) || 0,
        totalValue,
        status: OSStatus.FINALIZADO,
        paymentStatus,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };

      const currentOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      await syncData('orders', [...currentOrders, os]);

      setFinalOs(os);
      setStep('FINAL');
    } catch (error) {
      alert("ERRO NA SINCRONIZAÇÃO NEURAL.");
    } finally {
      setIsSaving(false);
    }
  };

  const downloadImage = async () => {
    if (!invoiceRef.current) return;
    const canvas = await html2canvas(invoiceRef.current, { 
      scale: 3, 
      backgroundColor: '#000000', 
      useCORS: true,
      windowWidth: 800
    });
    const link = document.createElement('a');
    link.download = `KAENPRO_NOTA_${finalOs?.osNumber}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  const isCompact = items.length > 8;

  return (
    <div className="flex flex-col min-h-screen bg-black text-white selection:bg-[#FF2D55]">
      {/* Header Fixo de Navegação */}
      <div className="p-8 border-b border-white/5 flex items-center justify-between glass-card sticky top-0 z-50 print:hidden">
        <button onClick={() => navigate(-1)} className="p-4 bg-white/5 rounded-full text-zinc-500 hover:text-white border border-white/10 transition-all">
          <ChevronLeft size={24} />
        </button>
        <h2 className="text-[11px] font-black uppercase tracking-[0.6em] italic">GERADOR DE NOTA <span className="text-[#FF2D55]">ELITE</span></h2>
        <div className="w-14"></div>
      </div>

      <div className="flex-1 overflow-y-auto p-6 md:p-12 no-scrollbar scroll-smooth">
        {step !== 'FINAL' ? (
          <div className="max-w-3xl mx-auto space-y-12 pb-40">

            {/* ETAPA 1: CLIENTE E VEÍCULO */}
            <div className="glass-card p-10 rounded-ios border border-white/10 space-y-10 shadow-3xl animate-in slide-in-from-bottom-8 duration-500">
               <div className="flex items-center gap-6">
                 <div className="w-14 h-14 bg-[#FF2D55] rounded-2xl flex items-center justify-center text-white shadow-[0_0_30px_rgba(255,45,85,0.4)]">
                   <User size={28}/>
                 </div>
                 <div>
                   <h3 className="text-xl font-black uppercase italic tracking-tighter">IDENTIFICAÇÃO</h3>
                   <p className="text-[9px] font-black text-zinc-600 uppercase tracking-widest">REGISTRO DE PROPRIETÁRIO E FROTA</p>
                 </div>
               </div>

               {!selectedClient ? (
                  <div className="relative group w-full">
                    <Search className="absolute left-8 top-1/2 -translate-y-1/2 text-zinc-800" size={24} />
                    <input 
                      type="text" value={clientSearch} onChange={(e) => setClientSearch(e.target.value)}
                      placeholder="DIGITE O NOME DO CLIENTE..."
                      className="w-full bg-black border-2 border-white/5 rounded-[2.2rem] py-8 pl-24 pr-8 text-sm font-black outline-none focus:border-[#FF2D55]/40 transition-all placeholder-zinc-900 uppercase tracking-widest"
                    />
                    {filteredClients.length > 0 && (
                       <div className="mt-6 space-y-2 max-h-64 overflow-y-auto no-scrollbar">
                         {filteredClients.map(c => (
                           <button key={c.id} onClick={() => setSelectedClient(c)} className="w-full p-8 bg-white/5 hover:bg-[#FF2D55] rounded-[2.2rem] flex items-center justify-between border border-white/5 transition-all group">
                             <span className="text-xs font-black uppercase italic tracking-widest">{c.name}</span>
                             <Plus size={20} className="text-[#FF2D55] group-hover:text-white" />
                           </button>
                         ))}
                       </div>
                    )}
                  </div>
               ) : (
                  <div className="bg-[#FF2D55]/5 p-10 rounded-ios border border-[#FF2D55]/20 flex items-center justify-between relative group animate-in zoom-in duration-300">
                    <div>
                      <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest mb-1 block italic">CLIENTE ATIVO</span>
                      <span className="text-3xl font-black uppercase italic text-white tracking-tighter">{selectedClient.name}</span>
                    </div>
                    <button onClick={() => {setSelectedClient(null); setSelectedVehicle(null);}} className="p-4 bg-black rounded-full text-zinc-600 hover:text-white border border-white/10 transition-all"><X size={20}/></button>
                  </div>
               )}

               {selectedClient && !selectedVehicle && (
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 animate-in slide-in-from-bottom-4 duration-500">
                    {clientVehicles.map(v => (
                      <button key={v.id} onClick={() => setSelectedVehicle(v)} className="p-8 bg-white/5 border border-white/5 rounded-ios hover:border-[#FF2D55]/50 transition-all text-center group">
                        <span className="text-3xl font-black text-white group-hover:text-[#FF2D55] transition-colors italic tracking-tighter uppercase block mb-1">{v.plate}</span>
                        <span className="text-[10px] font-bold text-zinc-600 uppercase tracking-widest">{v.model}</span>
                      </button>
                    ))}
                  </div>
               )}

               {selectedVehicle && (
                 <div className="bg-emerald-500/5 p-10 rounded-ios border border-emerald-500/20 flex items-center justify-between relative animate-in zoom-in duration-300">
                    <div>
                      <span className="text-[10px] font-black text-zinc-600 uppercase tracking-widest mb-1 block italic">VEÍCULO ALVO</span>
                      <span className="text-3xl font-black uppercase italic text-white tracking-tighter">{selectedVehicle.plate} • {selectedVehicle.model}</span>
                    </div>
                    <button onClick={() => setSelectedVehicle(null)} className="p-4 bg-black rounded-full text-zinc-600 hover:text-white border border-white/10 transition-all"><X size={20}/></button>
                 </div>
               )}
            </div>

            {/* ETAPA 2: ITENS E SERVIÇOS */}
            {selectedVehicle && (
               <div className="glass-card p-10 rounded-ios border border-white/10 space-y-12 shadow-3xl animate-in slide-in-from-bottom-8 duration-500">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-6">
                      <div className="w-14 h-14 bg-[#FF2D55] rounded-2xl flex items-center justify-center text-white shadow-[0_0_30px_rgba(255,45,85,0.4)]">
                        <Wrench size={28}/>
                      </div>
                      <div>
                        <h3 className="text-xl font-black uppercase italic tracking-tighter">COMPONENTES</h3>
                        <p className="text-[9px] font-black text-zinc-600 uppercase tracking-widest">DETALHAMENTO TÉCNICO E VALORES</p>
                      </div>
                    </div>
                    <button onClick={addItem} className="px-10 py-5 bg-[#FF2D55] rounded-[1.8rem] text-white font-black uppercase text-[11px] tracking-widest shadow-2xl hover:scale-105 active:scale-95 transition-all italic flex items-center gap-3">
                        <Plus size={20}/> ADICIONAR ITEM
                    </button>
                  </div>

                  <div className="space-y-4">
                    {items.map(item => (
                      <div key={item.id} className="bg-black p-6 rounded-[2.2rem] border border-white/5 space-y-6 group hover:border-white/10 transition-all">
                        <input 
                          type="text" placeholder="DESCRIÇÃO DO COMPONENTE OU SERVIÇO..." 
                          value={item.description} 
                          onChange={(e)=>updateItem(item.id, 'description', e.target.value.toUpperCase())} 
                          className="w-full bg-transparent text-sm font-black outline-none uppercase italic text-white placeholder-zinc-900 tracking-widest"
                        />
                        <div className="flex gap-4">
                           <input type="number" placeholder="QTD" value={item.quantity || ''} onChange={(e)=>updateItem(item.id, 'quantity', parseFloat(e.target.value) || 0)} className="w-24 bg-white/5 border border-white/5 p-5 rounded-2xl text-center text-sm font-black text-white outline-none"/>
                           <div className="flex-1 flex bg-white/5 border border-white/5 p-5 rounded-2xl">
                             <span className="text-zinc-700 font-black italic mr-4">R$</span>
                             <input type="number" placeholder="0,00" value={item.unitPrice || ''} onChange={(e)=>updateItem(item.id, 'unitPrice', parseFloat(e.target.value) || 0)} className="w-full bg-transparent text-sm font-black text-white outline-none placeholder-zinc-900"/>
                           </div>
                           <button onClick={()=>removeItem(item.id)} className="p-5 text-zinc-800 hover:text-[#FF2D55] transition-colors"><Trash2 size={24}/></button>
                        </div>
                      </div>
                    ))}
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                    <div className="space-y-4">
                      <label className="text-[9px] font-black text-zinc-700 tracking-[0.4em] italic uppercase ml-4">MÃO DE OBRA</label>
                      <input type="number" value={labor || ''} onChange={(e)=>setLabor(e.target.value)} placeholder="0,00" className="w-full bg-black border border-white/10 p-8 rounded-[2.2rem] text-2xl font-black outline-none focus:border-[#FF2D55] shadow-inner text-white tracking-tighter"/>
                    </div>
                    <div className="space-y-4">
                      <label className="text-[9px] font-black text-zinc-700 tracking-[0.4em] italic uppercase ml-4">SITUAÇÃO FINANCEIRA</label>
                      <select value={paymentStatus} onChange={(e)=>setPaymentStatus(e.target.value as PaymentStatus)} className="w-full bg-black border border-white/10 p-8 rounded-[2.2rem] text-[11px] font-black uppercase outline-none focus:border-[#FF2D55] shadow-inner text-white tracking-widest cursor-pointer">
                        <option value={PaymentStatus.PENDENTE}>AGUARDANDO PAGAMENTO</option>
                        <option value={PaymentStatus.PAGO}>PAGAMENTO CONFIRMADO</option>
                      </select>
                    </div>
                  </div>

                  <div className="p-16 bg-[#FF2D55]/5 rounded-ios border border-[#FF2D55]/10 flex flex-col items-center gap-4 text-center">
                    <span className="text-[11px] font-black uppercase text-zinc-700 tracking-[0.8em] italic">MONTANTE TOTAL DA NOTA</span>
                    <span className="text-6xl md:text-8xl font-black text-white italic tracking-tighter">R$ {totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</span>
