                 </div>
               )}
            </div>

            {/* ETAPA 2: ITENS E SERVIÇOS */}
            {selectedVehicle && (
               <div className="glass-card p-10 rounded-ios border border-white/10 space-y-12 animate-in slide-in-from-bottom-8">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-6">
