             <div className="invoice-preview-wrapper shadow-[0_60px_150px_rgba(0,0,0,0.8)]">
               <div ref={invoiceRef} className="kaen-invoice">
                  {/* Header Kaen */}
                  <div className="flex justify-between items-start mb-12 border-b border-zinc-100 pb-8">
