                        <p className="text-[10px] font-bold text-zinc-400 uppercase tracking-widest italic">{new Date(finalOs.createdAt).toLocaleDateString('pt-BR')}</p>
                     </div>
                  </div>

                  {/* Info Blocks Kaen */}
                  <div className="grid grid-cols-2 gap-6 mb-12">
                    <div className="bg-zinc-50 p-8 rounded-[2.5rem] border border-zinc-100 flex flex-col justify-center">
                      <p className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-3 italic">PROPRIETÁRIO</p>
                      <p className="text-2xl font-black uppercase leading-tight tracking-tighter">{selectedClient.name}</p>
                      <p className="text-[13px] font-bold text-zinc-500 mt-1">{selectedClient.phone}</p>
                    </div>
                    <div className="bg-zinc-50 p-8 rounded-[2.5rem] border border-zinc-100 flex flex-col justify-between">
                       <div className="flex justify-between items-start">
                        <div>
                          <p className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-3 italic">VEÍCULO</p>
                          <p className="text-2xl font-black uppercase leading-none tracking-tighter">{selectedVehicle.model}</p>
                          <p className="text-[12px] font-bold text-zinc-500 uppercase mt-2">{selectedVehicle.plate}</p>
                        </div>
                        <div className="text-right">
                          <p className="text-[9px] font-bold text-zinc-400 uppercase tracking-widest mb-3 italic">KM ATUAL</p>
                          <p className="text-xl font-black tracking-tighter">{selectedVehicle.km || '0'} km</p>
                        </div>
                       </div>
                    </div>
                  </div>

                  {/* Tabela de Itens Sem Cortes */}
                  <div className="flex-1 mb-8 overflow-visible">
                     <table className="w-full text-left">
                        <thead>
                          <tr className="text-[10px] font-bold text-zinc-300 uppercase tracking-widest border-b border-zinc-50">
                            <th className="pb-4 italic">DESCRIÇÃO</th>
                            <th className="pb-4 text-center px-4">QTD</th>
                            <th className="pb-4 text-right">UNITÁRIO</th>
                            <th className="pb-4 text-right">TOTAL</th>
                          </tr>
                        </thead>
                        <tbody className="font-bold text-zinc-800">
                          {finalOs.items.map((i,idx)=>(
                            <tr key={idx} className="border-b border-zinc-50/50">
                              <td className="text-[12px] py-4 uppercase leading-tight pr-6">{i.description}</td>
                              <td className="text-[12px] py-4 text-center text-zinc-400 px-4">{i.quantity}</td>
                              <td className="text-[12px] py-4 text-right text-zinc-400">R$ {i.unitPrice.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
                              <td className="text-[12px] py-4 text-right">R$ {(i.quantity*i.unitPrice).toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
                            </tr>
                          ))}
                          {finalOs.laborValue > 0 && (
                            <tr className="bg-zinc-50/30">
                              <td className="text-[12px] py-5 uppercase font-black">Mão de Obra Especializada</td>
                              <td className="text-[12px] py-5 text-center text-zinc-400">01</td>
                              <td className="text-[12px] py-5 text-right text-zinc-400">R$ {finalOs.laborValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
                              <td className="text-[12px] py-5 text-right font-black">R$ {finalOs.laborValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</td>
                            </tr>
                          )}
                        </tbody>
                     </table>
                  </div>

                  {/* Footer Kaen Equilibrado */}
                  <div className="mt-auto flex justify-between items-center border-t border-zinc-100 pt-8">
                     <div className="flex flex-col gap-8 flex-1">
                        <div className={`inline-flex self-start px-8 py-2.5 rounded-2xl border-2 text-[10px] font-black uppercase tracking-widest italic ${finalOs.paymentStatus === PaymentStatus.PAGO ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-amber-50 border-amber-100 text-amber-600'}`}>
                            PAGAMENTO: {finalOs.paymentStatus === PaymentStatus.PAGO ? 'EFETUADO' : 'PENDENTE'}
                        </div>
                        <div className="w-52 pt-4 border-t border-zinc-100">
