                      </div>
                    </div>

                    {/* Tabela de Itens */}
                    <div className="flex-1 mb-10 overflow-visible">
                       <table className="w-full text-left">
                          <thead>
                            <tr className="text-[11px] font-bold text-zinc-400 uppercase tracking-[0.2em] border-b-2 border-zinc-100 pb-4">
