    const target = document.getElementById('render-target-hidden');
    if (!target || !finalOs || !previewRef.current) return;

    setIsSaving(true);

    // Snapshot Limpo para Captura
    const clone = previewRef.current.cloneNode(true) as HTMLDivElement;
    clone.style.transform = 'none';
    clone.style.margin = '0';
    clone.style.boxShadow = 'none';
    clone.style.borderRadius = '50px';

    target.innerHTML = '';
    target.appendChild(clone);
    target.style.visibility = 'visible'; // Torna visível apenas no container oculto para o html2canvas ler

    try {
      const canvas = await html2canvas(clone, {
        scale: 2.5, 
        backgroundColor: "#ffffff",
        useCORS: true,
        logging: false,
        width: 720,
        height: 1280
      });

      const link = document.createElement('a');
