} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { ServiceOrder, OSStatus, UserSession, Appointment } from '../types';

const Dashboard: React.FC<{ session?: UserSession }> = ({ session }) => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<ServiceOrder[]>([]);
  const [appointments, setAppointments] = useState<Appointment[]>([]);

  useEffect(() => {
    if (session) {
      const savedOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      const savedApps = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_appointments`) || '[]');
      setOrders(savedOrders);
      setAppointments(savedApps);
    }
  }, [session]);

  const financialStats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];

    const calculateTotals = (data: ServiceOrder[]) => {
      const labor = data.reduce((acc, curr) => acc + curr.laborValue, 0);
      const total = data.reduce((acc, curr) => acc + curr.totalValue, 0);
      return { labor, parts: total - labor, total };
    };

    const daily = calculateTotals(orders.filter(o => o.createdAt.startsWith(today)));
    const all = calculateTotals(orders);

    // Previsão baseada em agendamentos (Ticket médio de R$ 450 se não especificado)
    const estimatedGain = appointments.filter(a => a.status === 'Agendado' || a.status === 'Pendente').length * 450;

    return { daily, all, estimatedGain };
  }, [orders, appointments]);

  const robotInsights = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const insights = [];

    const pendingApps = appointments.filter(a => a.date === today && a.status === 'Pendente');
    if (pendingApps.length > 0) {
      insights.push({ type: 'warning', text: `Robô detectou ${pendingApps.length} agendamentos pendentes para HOJE!`, icon: <AlertTriangle size={18}/> });
    }

    if (financialStats.daily.total === 0 && appointments.length < 2) {
      insights.push({ type: 'danger', text: "Fluxo de hoje está baixo. Robô sugere disparar avisos de revisão no WhatsApp.", icon: <Activity size={18}/> });
    }

    const lateOrders = orders.filter(o => o.status === OSStatus.EM_ANDAMENTO && new Date(o.createdAt) < new Date(Date.now() - 86400000));
    if (lateOrders.length > 0) {
      insights.push({ type: 'info', text: `${lateOrders.length} ordens de serviço estão em andamento há mais de 24h. Verificar atrasos.`, icon: <Clock size={18}/> });
    }

    return insights;
  }, [appointments, financialStats, orders]);

  return (
    <div className="space-y-10 animate-in fade-in duration-700 p-6 md:p-12 pb-40 w-full">

      {/* ROBOT ASSISTANT HEADER */}
      <div className="w-full glass-card p-10 rounded-[3.5rem] border border-[#FF2D55]/10 relative overflow-hidden group shadow-[0_40px_100px_rgba(255,45,85,0.08)]">
         <div className="absolute top-0 right-0 p-12 text-[#FF2D55] opacity-5 group-hover:opacity-10 transition-opacity">
            <Sparkles size={180} />
         </div>
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-8 relative z-10">
            <div>
               <div className="flex items-center gap-4 mb-4">
                  <div className="w-12 h-12 bg-[#FF2D55] rounded-2xl flex items-center justify-center text-white shadow-lg animate-pulse">
                     <Activity size={24} />
                  </div>
                  <h2 className="text-3xl font-black italic uppercase tracking-tighter">NEURAL <span className="text-[#FF2D55]">ASSISTANT</span></h2>
               </div>
               <p className="text-zinc-500 font-bold uppercase tracking-widest text-[10px] italic">Monitoramento em tempo real da oficina Kaenpro</p>
            </div>
            <div className="flex gap-4">
               <button onClick={() => navigate('/orders/new')} className="bg-[#FF2D55] px-8 py-4 rounded-full font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all flex items-center gap-3">
                  <PlusCircle size={18}/> Nova Nota
               </button>
               <button onClick={() => navigate('/calendar')} className="bg-white text-black px-8 py-4 rounded-full font-black uppercase text-[10px] tracking-widest shadow-xl active:scale-95 transition-all flex items-center gap-3">
                  <Calendar size={18}/> Ver Agenda
               </button>
            </div>
         </div>

         {/* Insights do Robô */}
         <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-12 border-t border-white/5 pt-10">
            {robotInsights.map((insight, idx) => (
               <div key={idx} className="flex items-center gap-4 bg-black/40 p-5 rounded-3xl border border-white/5 group hover:border-[#FF2D55]/30 transition-all">
                  <div className={`p-3 rounded-xl ${insight.type === 'danger' ? 'bg-red-500/10 text-red-500' : insight.type === 'warning' ? 'bg-amber-500/10 text-amber-500' : 'bg-blue-500/10 text-blue-500'}`}>
                     {insight.icon}
                  </div>
                  <p className="text-[11px] font-bold text-zinc-300 uppercase tracking-tight italic leading-relaxed">{insight.text}</p>
               </div>
            ))}
            {robotInsights.length === 0 && (
               <div className="col-span-2 flex items-center gap-4 bg-emerald-500/5 p-5 rounded-3xl border border-emerald-500/10">
                  <CheckCircle2 className="text-emerald-500" size={24} />
                  <p className="text-[11px] font-bold text-emerald-500 uppercase tracking-widest italic">Operação estável. Sem pendências críticas identificadas pelo robô.</p>
               </div>
            )}
         </div>
      </div>

      {/* FINANCIAL GRID - LABOR vs PARTS */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
         {/* HOJE */}
         <div className="glass-card p-10 rounded-[3rem] border border-white/5">
            <p className="text-zinc-600 font-black uppercase tracking-[0.2em] text-[9px] mb-6 italic">GANHOS DE HOJE</p>
            <div className="space-y-6">
               <div className="flex justify-between items-center p-6 bg-blue-500/5 border border-blue-500/10 rounded-3xl glow-labor">
                  <div>
                     <p className="text-[8px] font-black text-blue-500 uppercase tracking-widest mb-1 italic">MÃO DE OBRA</p>
                     <p className="text-2xl font-black italic">R$ {financialStats.daily.labor.toLocaleString('pt-BR')}</p>
                  </div>
                  <Wrench className="text-blue-500/30" size={32} />
               </div>
               <div className="flex justify-between items-center p-6 bg-[#FF2D55]/5 border border-[#FF2D55]/10 rounded-3xl glow-parts">
                  <div>
                     <p className="text-[8px] font-black text-[#FF2D55] uppercase tracking-widest mb-1 italic">PEÇAS / INSUMOS</p>
                     <p className="text-2xl font-black italic">R$ {financialStats.daily.parts.toLocaleString('pt-BR')}</p>
                  </div>
                  <Package className="text-[#FF2D55]/30" size={32} />
               </div>
            </div>
         </div>

         {/* MÊS / ACUMULADO */}
         <div className="glass-card p-10 rounded-[3rem] border border-white/5 bg-gradient-to-br from-zinc-900/50 to-transparent">
            <p className="text-zinc-600 font-black uppercase tracking-[0.2em] text-[9px] mb-6 italic">ACUMULADO GERAL</p>
            <div className="space-y-2 mb-10">
               <p className="text-5xl font-black italic text-white tracking-tighter">R$ {financialStats.all.total.toLocaleString('pt-BR')}</p>
               <p className="text-[10px] font-black text-emerald-500 uppercase tracking-widest italic flex items-center gap-2">
                  <TrendingUp size={12}/> CRESCIMENTO DE 12% NESTE MÊS
               </p>
            </div>
            <div className="grid grid-cols-2 gap-4">
               <div className="p-5 bg-white/5 rounded-2xl">
                  <p className="text-[8px] font-black text-zinc-500 uppercase mb-1">Peças</p>
                  <p className="text-sm font-black italic">R$ {financialStats.all.parts.toLocaleString('pt-BR')}</p>
               </div>
               <div className="p-5 bg-white/5 rounded-2xl">
                  <p className="text-[8px] font-black text-zinc-500 uppercase mb-1">Mão de Obra</p>
                  <p className="text-sm font-black italic">R$ {financialStats.all.labor.toLocaleString('pt-BR')}</p>
               </div>
            </div>
         </div>

         {/* PREVISÃO ROBÔ */}
         <div className="glass-card p-10 rounded-[3rem] border border-emerald-500/10 bg-emerald-500/5">
            <div className="flex justify-between items-start mb-6">
               <p className="text-emerald-500 font-black uppercase tracking-[0.2em] text-[9px] italic">PREVISÃO DE GANHOS</p>
               <Sparkles className="text-emerald-500/50" size={20} />
            </div>
            <div className="space-y-2">
               <p className="text-4xl font-black italic text-white tracking-tighter">~R$ {financialStats.estimatedGain.toLocaleString('pt-BR')}</p>
               <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest italic leading-relaxed">
                  Estimativa baseada em agendamentos futuros confirmados pelo robô.
               </p>
            </div>
            <div className="mt-10 pt-10 border-t border-emerald-500/10">
               <button onClick={() => navigate('/calendar')} className="w-full bg-emerald-500 text-black py-5 rounded-2xl font-black uppercase text-[10px] tracking-widest flex items-center justify-center gap-3 active:scale-95 transition-all italic">
                  Otimizar Agenda <ArrowRight size={16}/>
               </button>
            </div>
         </div>
      </div>

      {/* QUICK ACTIONS ROBÔ */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
         {[
           { label: 'Relatório WhatsApp', icon: <MessageCircle/>, path: '/billing', color: 'text-emerald-500' },
           { label: 'Controle de Atrasos', icon: <Activity/>, path: '/orders', color: 'text-amber-500' },
           { label: 'Status Peças', icon: <Package/>, path: '/inventory', color: 'text-[#FF2D55]' },
           { label: 'Terminal Móvel', icon: <Smartphone/>, path: '/terminal', color: 'text-blue-500' }
         ].map((action, idx) => (
           <button key={idx} onClick={() => navigate(action.path)} className="glass-card p-8 rounded-[2.5rem] border border-white/5 flex flex-col items-center gap-4 hover:bg-white/5 transition-all group">
              <div className={`w-14 h-14 bg-white/5 rounded-2xl flex items-center justify-center ${action.color} group-hover:scale-110 transition-transform`}>
                 {action.icon}
              </div>
              <p className="text-[10px] font-black uppercase tracking-widest italic text-zinc-500 group-hover:text-white transition-colors">{action.label}</p>
           </button>
         ))}
      </div>

    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import { 
  Plus, Trash2, Wrench, ChevronLeft, X,
  User, Search, Loader2, Check, ImageIcon, Car, Info, Download, Phone, Package
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { Client, Vehicle, OSItem, OSStatus, ServiceOrder, PaymentStatus, UserSession } from '../types';
import html2canvas from 'html2canvas';

const NewServiceOrder: React.FC<{ session?: UserSession; syncData?: (key: string, data: any) => Promise<void> }> = ({ session, syncData }) => {
  const navigate = useNavigate();
  const previewRef = useRef<HTMLDivElement>(null);

  const [step, setStep] = useState<'CLIENTE' | 'VEICULO' | 'ITENS' | 'FINAL'>('CLIENTE');
  const [clients, setClients] = useState<Client[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [clientSearch, setClientSearch] = useState('');

  const [selectedClient, setSelectedClient] = useState<Client | null>(null);
  const [selectedVehicle, setSelectedVehicle] = useState<Vehicle | null>(null);

  const [items, setItems] = useState<OSItem[]>([]);
  const [labor, setLabor] = useState<string>('0');
  const [paymentStatus, setPaymentStatus] = useState<PaymentStatus>(PaymentStatus.PENDENTE);

  const [finalOs, setFinalOs] = useState<ServiceOrder | null>(null);
  const [isSaving, setIsSaving] = useState(false);

  useEffect(() => {
    if (session) {
      const savedClients = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_clients`) || '[]');
      const savedVehicles = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_vehicles`) || '[]');
      setClients(savedClients);
      setVehicles(savedVehicles);
    }
  }, [session]);

  const totalValue = useMemo(() => {
    const itemsTotal = items.reduce((acc, curr) => acc + (curr.quantity * curr.unitPrice), 0);
    return itemsTotal + (parseFloat(labor) || 0);
  }, [items, labor]);

  const handleFinalize = async () => {
    if (!selectedClient || !selectedVehicle || !session || !syncData) return;
    setIsSaving(true);
    try {
      const osNumber = `${Math.floor(100000 + Math.random() * 899999)}`;
      const os: ServiceOrder = {
        id: Math.random().toString(36).substr(2, 9),
        osNumber,
        clientId: selectedClient.id,
        clientName: selectedClient.name,
        vehicleId: selectedVehicle.id,
        vehiclePlate: selectedVehicle.plate,
        vehicleModel: selectedVehicle.model,
        vehicleKm: selectedVehicle.km.toString(),
        problem: 'SERVIÇO DE MANUTENÇÃO ELITE',
        items,
        laborValue: parseFloat(labor) || 0,
        discount: 0,
        totalValue,
        status: OSStatus.FINALIZADO,
        paymentStatus,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString()
      };
      const currentOrders = JSON.parse(localStorage.getItem(`kaenpro_${session.username}_orders`) || '[]');
      await syncData('orders', [...currentOrders, os]);
      setFinalOs(os);
      setStep('FINAL');
    } catch (error) {
      alert("ERRO NO PROCESSAMENTO.");
    } finally {
      setIsSaving(false);
    }
  };

  const downloadImage = async () => {
    const target = document.getElementById('render-target-hidden');
    if (!target || !finalOs || !previewRef.current) return;

    setIsSaving(true);

    // RENDERIZAÇÃO LIMPA PARA FOTO
    const clone = previewRef.current.cloneNode(true) as HTMLDivElement;
    clone.style.transform = 'none';
    clone.style.margin = '0';
    clone.style.borderRadius = '0'; 

    target.innerHTML = '';
    target.appendChild(clone);

    try {
      const canvas = await html2canvas(clone, {
        scale: 2.5, // Ultra-fino
        backgroundColor: "#ffffff",
        useCORS: true,
        logging: false,
        width: 720,
        height: 1280
      });

      const link = document.createElement('a');
      link.download = `KAEN_OS_${finalOs.osNumber}.png`;
      link.href = canvas.toDataURL('image/png', 1.0);
      link.click();
    } catch (err) {
      alert("Erro ao capturar imagem.");
    } finally {
      target.innerHTML = ''; 
      setIsSaving(false);
    }
  };

  const densityClass = useMemo(() => {
    const totalLines = items.length + (parseFloat(labor) > 0 ? 1 : 0);
    if (totalLines > 18) return 'micro-mode';
    if (totalLines > 10) return 'compact-mode';
    return '';
  }, [items, labor]);

  const InvoiceTemplate = ({ os }: { os: ServiceOrder }) => (
    <div className={`kaen-invoice-render ${densityClass}`}>
      {/* HEADER BLINDADO */}
      <div className="inv-section-header">
        <div className="flex justify-between items-start h-full">
          <div className="flex flex-col gap-4">
