                 SITUAÇÃO: {os.paymentStatus === PaymentStatus.PAGO ? 'PAGAMENTO CONCLUÍDO' : 'PENDENTE DE PAGAMENTO'}
              </div>
              <div className="w-40 pt-4 border-t border-zinc-200">
                 <p className="text-[8px] font-black text-zinc-300 uppercase text-center tracking-widest italic leading-none">ASSINATURA DIGITAL</p>
              </div>
           </div>

           <div className="bg-black px-12 py-8 rounded-[3rem] flex flex-col items-end shadow-2xl">
              <p className="text-[10px] font-black text-zinc-500 uppercase tracking-widest mb-2 italic">VALOR TOTAL LÍQUIDO</p>
              <p className="text-5xl font-black text-white italic tracking-tighter leading-none">R$ {os.totalValue.toLocaleString('pt-BR', { minimumFractionDigits: 2 })}</p>
           </div>
        </div>
      </div>

      <div className="absolute bottom-6 left-0 w-full text-center">
         <p className="text-[9px] font-black text-zinc-200 uppercase tracking-[0.5em] italic">KAEN MECÂNICA • PROTOCOLO PERFORMANCE V26</p>
      </div>
    </div>
  );

  return (
    <div className="flex flex-col min-h-screen bg-black text-white items-center w-full">
      <div className="w-full p-6 flex items-center justify-between glass-card sticky top-0 z-50 rounded-b-[2rem]">
        <button onClick={() => navigate(-1)} className="p-4 bg-white/5 rounded-full text-zinc-500 hover:text-white border border-white/10 active:scale-90 transition-all">
          <ChevronLeft size={24} />
        </button>
        <h2 className="text-[11px] font-black uppercase tracking-[0.5em] italic">PROTOCOLO <span className="text-[#FF2D55]">KAEN</span></h2>
        <div className="w-16"></div>
      </div>

      <div className="flex-1 w-full max-w-4xl p-6 md:p-12 space-y-12 pb-40 flex flex-col items-center">

        {step === 'CLIENTE' && (
