import NewServiceOrder from './views/NewServiceOrder';
import Inventory from './views/Inventory';
import Clients from './views/Clients';
import ClientDetails from './views/ClientDetails';
import Vehicles from './views/Vehicles';
import VehicleDetails from './views/VehicleDetails';
import Employees from './views/Employees';
import Billing from './views/Billing';
import Financial from './views/Financial';
import Calendar from './views/Calendar';
import MechanicTerminal from './views/MechanicTerminal';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import { SyncStatus, UserSession } from './types';

const App: React.FC = () => {
  const [session, setSession] = useState<UserSession | null>(null);
  const [syncStatus, setSyncStatus] = useState<SyncStatus>(SyncStatus.SYNCED);

  useEffect(() => {
    const savedSession = sessionStorage.getItem('kaen_session');
    if (savedSession) {
      try {
        setSession(JSON.parse(savedSession));
      } catch (e) {
        sessionStorage.removeItem('kaen_session');
      }
    }
  }, []);

  const performCloudSync = useCallback(async (action: string) => {
    setSyncStatus(SyncStatus.SYNCING);
    await new Promise(r => setTimeout(r, 800));
    setSyncStatus(SyncStatus.SYNCED);
  }, []);

  const handleLogin = (username: string, role: 'Dono' | 'Funcionário' | 'Recepção') => {
    const newSession: UserSession = { username, role, lastSync: new Date().toISOString() };
    setSession(newSession);
    sessionStorage.setItem('kaen_session', JSON.stringify(newSession));
    performCloudSync('Full Fetch');
  };

  const handleLogout = () => {
    setSession(null);
    sessionStorage.removeItem('kaen_session');
  };

  const syncData = async (key: string, data: any) => {
    if (!session) return;
    const userKey = `kaen_${session.username}_${key}`;
    localStorage.setItem(userKey, JSON.stringify(data));
    await performCloudSync(`Update ${key}`);
  };

  const PrivateLayout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);

    if (!session) return <Navigate to="/login" replace />;

    return (
      <div className="flex h-screen bg-black overflow-hidden relative">
        <Sidebar 
          role={session.role} 
          isOpen={isSidebarOpen} 
          onClose={() => setIsSidebarOpen(false)} 
        />

        <div className="flex-1 flex flex-col min-w-0 relative">
          <Header 
            role={session.role} 
            username={session.username}
            syncStatus={syncStatus}
            onLogout={handleLogout} 
            onToggleSidebar={() => setIsSidebarOpen(!isSidebarOpen)}
          />

          <main className="flex-1 overflow-y-auto overflow-x-visible bg-[#050505] scroll-smooth overscroll-contain no-scrollbar flex flex-col items-center">
            <div className="w-full max-w-[1200px] min-h-full flex flex-col items-center overflow-x-visible">
              {React.isValidElement(children) 
                ? React.cloneElement(children as React.ReactElement<any>, { session, syncData })
                : children}
            </div>
          </main>
        </div>
      </div>
    );
  };

  return (
    <Router>
      <Routes>
        <Route path="/" element={<LandingPage />} />
        <Route path="/login" element={session ? <Navigate to="/dashboard" replace /> : <LoginPage onLogin={handleLogin} />} />
        <Route path="/dashboard" element={<PrivateLayout><Dashboard /></PrivateLayout>} />
        <Route path="/calendar" element={<PrivateLayout><Calendar /></PrivateLayout>} />
        <Route path="/orders" element={<PrivateLayout><ServiceOrders role={session?.role} /></PrivateLayout>} />
        <Route path="/orders/new" element={<PrivateLayout><NewServiceOrder /></PrivateLayout>} />
        <Route path="/billing" element={<PrivateLayout><Billing /></PrivateLayout>} />
        <Route path="/financial" element={<PrivateLayout><Financial /></PrivateLayout>} />
        <Route path="/inventory" element={<PrivateLayout><Inventory /></PrivateLayout>} />
        <Route path="/clients" element={<PrivateLayout><Clients role={session?.role || 'Dono'} /></PrivateLayout>} />
        <Route path="/clients/:id" element={<PrivateLayout><ClientDetails role={session?.role || 'Dono'} /></PrivateLayout>} />
        <Route path="/vehicles" element={<PrivateLayout><Vehicles /></PrivateLayout>} />
        <Route path="/vehicles/:id" element={<PrivateLayout><VehicleDetails /></PrivateLayout>} />
        <Route path="/employees" element={<PrivateLayout><Employees /></PrivateLayout>} />
        <Route path="/terminal" element={<PrivateLayout><MechanicTerminal /></PrivateLayout>} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
};

export default App;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  PlusCircle, Sparkles, Loader2, Calendar, 
  TrendingUp, Activity, AlertTriangle, CheckCircle2,
  DollarSign, Wrench, Package, ArrowRight, Smartphone, MessageCircle,
  Clock
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { ServiceOrder, OSStatus, UserSession, Appointment } from '../types';

const Dashboard: React.FC<{ session?: UserSession }> = ({ session }) => {
  const navigate = useNavigate();
  const [orders, setOrders] = useState<ServiceOrder[]>([]);
  const [appointments, setAppointments] = useState<Appointment[]>([]);

  useEffect(() => {
    if (session) {
      const savedOrders = JSON.parse(localStorage.getItem(`kaen_${session.username}_orders`) || '[]');
      const savedApps = JSON.parse(localStorage.getItem(`kaen_${session.username}_appointments`) || '[]');
      setOrders(savedOrders);
      setAppointments(savedApps);
    }
  }, [session]);

  const financialStats = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];

    const calculateTotals = (data: ServiceOrder[]) => {
      const labor = data.reduce((acc, curr) => acc + curr.laborValue, 0);
      const total = data.reduce((acc, curr) => acc + curr.totalValue, 0);
      return { labor, parts: total - labor, total };
    };

    const daily = calculateTotals(orders.filter(o => o.createdAt.startsWith(today)));
    const all = calculateTotals(orders);
    const estimatedGain = appointments.filter(a => a.status === 'Agendado' || a.status === 'Pendente').length * 550;

    return { daily, all, estimatedGain };
  }, [orders, appointments]);

  const robotInsights = useMemo(() => {
    const today = new Date().toISOString().split('T')[0];
    const insights = [];

    const pendingApps = appointments.filter(a => a.date === today && a.status === 'Pendente');
    if (pendingApps.length > 0) {
      insights.push({ type: 'warning', text: `Detectamos ${pendingApps.length} agendamentos pendentes para HOJE!`, icon: <AlertTriangle size={18}/> });
    }

    if (financialStats.daily.total === 0 && appointments.length < 3) {
      insights.push({ type: 'danger', text: "Fluxo diário baixo. Robô sugere disparar lembretes via WhatsApp.", icon: <Activity size={18}/> });
    }

    const lateOrders = orders.filter(o => o.status === OSStatus.EM_ANDAMENTO && new Date(o.createdAt) < new Date(Date.now() - 86400000));
    if (lateOrders.length > 0) {
      insights.push({ type: 'info', text: `${lateOrders.length} ordens de serviço pendentes há mais de 24h. Verificar atrasos.`, icon: <Clock size={18}/> });
    }

    return insights;
  }, [appointments, financialStats, orders]);

  return (
    <div className="space-y-12 animate-in fade-in duration-700 p-6 md:p-14 pb-48 w-full max-w-[1400px]">

      {/* ROBOT ASSISTANT HEADER */}
      <div className="w-full glass-card p-12 rounded-[4rem] border border-[#FF2D55]/20 relative overflow-hidden group shadow-[0_50px_120px_rgba(255,45,85,0.12)]">
         <div className="absolute top-0 right-0 p-16 text-[#FF2D55] opacity-5 group-hover:opacity-10 transition-opacity">
            <Sparkles size={220} />
         </div>
         <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-10 relative z-10">
            <div>
               <div className="flex items-center gap-5 mb-5">
                  <div className="w-14 h-14 bg-[#FF2D55] rounded-2xl flex items-center justify-center text-white shadow-xl animate-pulse border border-white/20">
                     <Activity size={28} />
                  </div>
                  <h2 className="text-4xl font-black italic uppercase tracking-tighter text-left">ASSISTENTE <span className="text-[#FF2D55]">NEURAL</span></h2>
               </div>
               <p className="text-zinc-500 font-bold uppercase tracking-[0.3em] text-[10px] italic text-left">Protocolos KAEN de monitoramento bionético em tempo real</p>
            </div>
            <div className="flex gap-5">
               <button onClick={() => navigate('/orders/new')} className="bg-[#FF2D55] px-10 py-5 rounded-full font-black uppercase text-[11px] tracking-widest shadow-xl active:scale-95 transition-all flex items-center gap-3">
                  <PlusCircle size={20}/> Nova Nota
               </button>
               <button onClick={() => navigate('/calendar')} className="bg-white text-black px-10 py-5 rounded-full font-black uppercase text-[11px] tracking-widest shadow-xl active:scale-95 transition-all flex items-center gap-3">
                  <Calendar size={20}/> Ver Agenda
               </button>
            </div>
         </div>

         {/* Insights do Robô */}
         <div className="grid grid-cols-1 md:grid-cols-2 gap-5 mt-14 border-t border-white/5 pt-12">
            {robotInsights.map((insight, idx) => (
               <div key={idx} className="flex items-center gap-5 bg-black/50 p-6 rounded-[2.5rem] border border-white/5 group hover:border-[#FF2D55]/40 transition-all cursor-default">
                  <div className={`p-4 rounded-2xl ${insight.type === 'danger' ? 'bg-red-500/10 text-red-500' : insight.type === 'warning' ? 'bg-amber-500/10 text-amber-500' : 'bg-blue-500/10 text-blue-500'}`}>
                     {insight.icon}
                  </div>
                  <p className="text-[12px] font-black text-zinc-300 uppercase tracking-tight italic leading-relaxed text-left">{insight.text}</p>
               </div>
            ))}
            {robotInsights.length === 0 && (
               <div className="col-span-2 flex items-center gap-5 bg-emerald-500/5 p-6 rounded-[2.5rem] border border-emerald-500/10">
                  <CheckCircle2 className="text-emerald-500" size={32} />
                  <p className="text-[12px] font-black text-emerald-500 uppercase tracking-widest italic">Sistema estável. Sem intercorrências críticas registradas.</p>
               </div>
            )}
         </div>
      </div>

      {/* FINANCE GRID */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
         <div className="glass-card p-12 rounded-[3.5rem] border border-white/5 shadow-2xl">
            <p className="text-zinc-600 font-black uppercase tracking-[0.3em] text-[10px] mb-8 italic text-left">MOVIMENTAÇÃO HOJE</p>
            <div className="space-y-8">
               <div className="flex justify-between items-center p-8 bg-blue-500/5 border border-blue-500/10 rounded-[2.5rem] shadow-inner">
                  <div className="text-left">
                     <p className="text-[9px] font-black text-blue-500 uppercase tracking-widest mb-2 italic">MÃO DE OBRA</p>
                     <p className="text-3xl font-black italic">R$ {financialStats.daily.labor.toLocaleString('pt-BR')}</p>
                  </div>
                  <Wrench className="text-blue-500/30" size={40} />
               </div>
               <div className="flex justify-between items-center p-8 bg-[#FF2D55]/5 border border-[#FF2D55]/10 rounded-[2.5rem] shadow-inner">
                  <div className="text-left">
                     <p className="text-[9px] font-black text-[#FF2D55] uppercase tracking-widest mb-2 italic">PEÇAS & PRODUTOS</p>
                     <p className="text-3xl font-black italic">R$ {financialStats.daily.parts.toLocaleString('pt-BR')}</p>
                  </div>
                  <Package className="text-[#FF2D55]/30" size={40} />
               </div>
            </div>
         </div>

         <div className="glass-card p-12 rounded-[3.5rem] border border-white/5 bg-gradient-to-br from-zinc-900/50 to-transparent shadow-2xl">
            <p className="text-zinc-600 font-black uppercase tracking-[0.3em] text-[10px] mb-8 italic text-left">PERFORMANCE ACUMULADA</p>
            <div className="space-y-4 mb-14 text-left">
               <p className="text-6xl font-black italic text-white tracking-tighter leading-none">R$ {financialStats.all.total.toLocaleString('pt-BR')}</p>
               <p className="text-[11px] font-black text-emerald-500 uppercase tracking-widest italic flex items-center gap-3 bg-emerald-500/5 py-2 px-4 rounded-full w-fit">
                  <TrendingUp size={16}/> CRESCIMENTO DE 14.5% 
               </p>
            </div>
            <div className="grid grid-cols-2 gap-5 text-left">
               <div className="p-7 bg-white/5 rounded-3xl border border-white/5">
                  <p className="text-[9px] font-black text-zinc-500 uppercase mb-2">Peças</p>
                  <p className="text-lg font-black italic">R$ {financialStats.all.parts.toLocaleString('pt-BR')}</p>
               </div>
               <div className="p-7 bg-white/5 rounded-3xl border border-white/5">
                  <p className="text-[9px] font-black text-zinc-500 uppercase mb-2">Serviços</p>
                  <p className="text-lg font-black italic">R$ {financialStats.all.labor.toLocaleString('pt-BR')}</p>
               </div>
            </div>
         </div>

         <div className="glass-card p-12 rounded-[3.5rem] border border-emerald-500/20 bg-emerald-500/5 shadow-2xl">
            <div className="flex justify-between items-start mb-8">
               <p className="text-emerald-500 font-black uppercase tracking-[0.3em] text-[10px] italic">PREVISÃO (IA)</p>
               <Sparkles className="text-emerald-500/40" size={24} />
            </div>
            <div className="space-y-4 text-left">
               <p className="text-5xl font-black italic text-white tracking-tighter leading-none">~R$ {financialStats.estimatedGain.toLocaleString('pt-BR')}</p>
               <p className="text-[11px] font-black text-zinc-500 uppercase tracking-widest italic leading-relaxed">
                  Estimativa baseada em agendamentos futuros e solicitações pendentes.
               </p>
            </div>
            <div className="mt-14 pt-14 border-t border-emerald-500/10">
               <button onClick={() => navigate('/calendar')} className="w-full bg-emerald-500 text-black py-6 rounded-3xl font-black uppercase text-[11px] tracking-[0.2em] flex items-center justify-center gap-4 active:scale-95 transition-all italic shadow-xl">
                  Otimizar Agenda <ArrowRight size={20}/>
               </button>
            </div>
         </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { NavLink } from 'react-router-dom';
import { 
  LayoutDashboard, Users, Car, PlusSquare, FileText, Package, UserCheck,
  Settings, Wrench, ChevronRight, DollarSign, Smartphone, X, PieChart, CalendarDays
} from 'lucide-react';

interface SidebarProps {
  role: 'Dono' | 'Funcionário' | 'Recepção';
  isOpen: boolean;
  onClose: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ role, isOpen, onClose }) => {
  const menuItems = [
    { name: 'Dashboard', icon: LayoutDashboard, path: '/dashboard', roles: ['Dono', 'Funcionário', 'Recepção'] },
    { name: 'Agenda Pro', icon: CalendarDays, path: '/calendar', roles: ['Dono', 'Recepção', 'Funcionário'] },
    { name: 'Terminal Pista', icon: Smartphone, path: '/terminal', roles: ['Dono', 'Funcionário'] },
    { name: 'Emitir Nota', icon: PlusSquare, path: '/orders/new', roles: ['Dono', 'Recepção', 'Funcionário'] },
    { name: 'Notas Geradas', icon: FileText, path: '/orders', roles: ['Dono', 'Recepção', 'Funcionário'] },
    { name: 'Fluxo de Caixa', icon: PieChart, path: '/financial', roles: ['Dono'] },
    { name: 'Cobranças', icon: DollarSign, path: '/billing', roles: ['Dono', 'Recepção'] },
    { name: 'Clientes', icon: Users, path: '/clients', roles: ['Dono', 'Recepção'] },
    { name: 'Veículos', icon: Car, path: '/vehicles', roles: ['Dono', 'Recepção', 'Funcionário'] },
    { name: 'Estoque', icon: Package, path: '/inventory', roles: ['Dono', 'Recepção'] },
    { name: 'Equipe KAEN', icon: UserCheck, path: '/employees', roles: ['Dono'] },
  ];

  const filteredItems = menuItems.filter(item => item.roles.includes(role));

  return (
    <>
      {isOpen && (
        <div 
          className="fixed inset-0 bg-black/90 backdrop-blur-md z-[140] animate-in fade-in duration-500 lg:hidden" 
          onClick={onClose} 
        />
      )}

      <aside className={`
        fixed inset-y-8 left-8 z-[150] w-[21rem] glass-card rounded-[3.5rem] transition-all duration-700 transform ease-[cubic-bezier(0.32,0.72,0,1)] flex flex-col overflow-hidden shadow-[0_50px_120px_rgba(0,0,0,0.9)] border-white/10
        ${isOpen ? 'translate-x-0 opacity-100' : '-translate-x-[125%] opacity-0 pointer-events-none lg:translate-x-0 lg:opacity-100 lg:pointer-events-auto'}
        lg:relative lg:inset-y-0 lg:left-0 lg:m-8 lg:mr-0
      `}>
        <div className="p-12 flex items-center justify-between flex-shrink-0">
          <div className="flex items-center space-x-5">
            <div className="w-14 h-14 bg-[#FF2D55] rounded-2xl flex items-center justify-center shadow-lg shadow-[#FF2D55]/30 border border-white/20">
              <Wrench className="text-white w-8 h-8" />
            </div>
            <div className="flex flex-col">
              <span className="text-3xl font-black tracking-tighter text-white uppercase italic leading-none">KAEN</span>
              <span className="text-[9px] font-bold text-zinc-600 uppercase tracking-[0.4em] mt-1 italic">BEYOND LIMITS</span>
            </div>
          </div>
          <button onClick={onClose} className="p-4 bg-white/5 hover:bg-[#FF2D55] rounded-2xl text-zinc-500 hover:text-white transition-all active:scale-90 lg:hidden">
            <X size={24}/>
          </button>
        </div>

        <nav className="flex-1 overflow-y-auto px-8 space-y-4 no-scrollbar pb-16">
          {filteredItems.map((item) => (
            <NavLink
              key={item.path} to={item.path} onClick={onClose}
              className={({ isActive }) => `
                flex items-center justify-between px-7 py-5 rounded-[2.5rem] transition-all duration-500 group relative
                ${isActive 
                  ? 'bg-[#FF2D55] text-white shadow-[0_25px_60px_rgba(255,45,85,0.4)]' 
                  : 'text-zinc-500 hover:bg-white/5 hover:text-white'}
              `}
            >
              {({ isActive }) => (
                <>
                  <div className="flex items-center space-x-6">
                    <item.icon size={24} className={isActive ? 'text-white' : 'text-zinc-600 group-hover:text-[#FF2D55]'} />
                    <span className="font-black text-[11px] uppercase tracking-[0.2em] italic">{item.name}</span>
                  </div>
                  {isActive && <div className="w-2.5 h-2.5 bg-white rounded-full animate-pulse shadow-[0_0_10px_white]"></div>}
                </>
              )}
            </NavLink>
          ))}
        </nav>

        <div className="p-10 border-t border-white/5 bg-zinc-950/20">
           <div className="flex items-center gap-4 text-zinc-700 hover:text-zinc-400 cursor-pointer transition-colors group">
              <Settings size={20} className="group-hover:rotate-45 transition-transform" />
              <span className="text-[10px] font-black uppercase tracking-widest italic">Ajustes KAEN</span>
           </div>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;
